-- =====================================================================
-- testPike fresh-install bootstrap (one-shot init for a brand-new database)
-- Generated by merging db/migration/V1..V* in version order (sort -V),
--           plus a trailing patch section for objects first applied by hand.
-- Use: auto-runs from docker-entrypoint-initdb.d on an empty volume, or psql -v ON_ERROR_STOP=1 -f.
-- Never run this on an existing database; upgrades replay db/migration/ incrementally.
-- Maintenance: rerun tools/ops/gen_schema_init.sh after adding a migration (idempotent; do not hand-edit this artifact).
-- =====================================================================

-- ################ V1__init.sql ################
-- =====================================================================
--               / tp_test_case / tp_case_step / tp_script / tp_audit_log / tp_ai_call_log
--   docker exec -i testpike-postgres psql -U testpike -d testpike < db/migration/V1__init.sql
-- =====================================================================

CREATE EXTENSION IF NOT EXISTS pg_trgm;
CREATE EXTENSION IF NOT EXISTS vector;

-- ---------------------------------------------------------------------
-- ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS tp_project (
    id               BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    name             VARCHAR(100) NOT NULL,
    code             VARCHAR(20)  NOT NULL UNIQUE,
    default_lang     VARCHAR(10)  NOT NULL DEFAULT 'zh-CN',
    default_priority VARCHAR(8),
    status           SMALLINT     NOT NULL DEFAULT 1,
    budget_monthly   DECIMAL(12,2),
    template_pack_id BIGINT,
    created_by       BIGINT,
    created_at       TIMESTAMP    NOT NULL DEFAULT now(),
    updated_at       TIMESTAMP    NOT NULL DEFAULT now()
);
COMMENT ON TABLE  tp_project IS '项目';
COMMENT ON COLUMN tp_project.status IS '1=活跃 2=已归档（软状态，不物理删）';

-- ---------------------------------------------------------------------
-- ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS tp_project_env (
    id               BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    project_id       BIGINT        NOT NULL REFERENCES tp_project(id),
    name             VARCHAR(50)   NOT NULL,                -- dev/test/staging
    env_type         SMALLINT      NOT NULL DEFAULT 1,
    base_url         VARCHAR(500),
    config_json      JSONB,
    end_types        VARCHAR(50)   NOT NULL DEFAULT 'web',
    browsers         VARCHAR(50)   NOT NULL DEFAULT 'chromium',
    health_status    SMALLINT      NOT NULL DEFAULT 0,
    version_snapshot VARCHAR(100),
    created_at       TIMESTAMP     NOT NULL DEFAULT now(),
    updated_at       TIMESTAMP     NOT NULL DEFAULT now(),
    CONSTRAINT uq_project_env_name UNIQUE (project_id, name),
    CONSTRAINT ck_project_env_type CHECK (env_type IN (1, 2)),
    CONSTRAINT ck_project_env_health CHECK (health_status IN (0, 1, 2))
);
COMMENT ON TABLE  tp_project_env IS '项目环境';
COMMENT ON COLUMN tp_project_env.env_type IS '1=测试 2=生产（生产默认禁执行，执行前强校验 base_url 与生产域名黑名单）';

-- ---------------------------------------------------------------------
-- ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS tp_user_project (
    id         BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    project_id BIGINT   NOT NULL REFERENCES tp_project(id),
    user_id    BIGINT   NOT NULL,
    role       SMALLINT NOT NULL DEFAULT 1,
    created_at TIMESTAMP NOT NULL DEFAULT now(),
    updated_at TIMESTAMP NOT NULL DEFAULT now(),
    CONSTRAINT uq_user_project UNIQUE (project_id, user_id),
    CONSTRAINT ck_user_project_role CHECK (role IN (1, 2))
);
COMMENT ON TABLE  tp_user_project IS '用户-项目-角色';
COMMENT ON COLUMN tp_user_project.role IS '1=成员 2=项目负责人';

-- ---------------------------------------------------------------------
-- ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS tp_requirement (
    id                  BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    project_id          BIGINT       NOT NULL REFERENCES tp_project(id),
    source              SMALLINT     NOT NULL DEFAULT 3,
    source_id           VARCHAR(100),
    title               VARCHAR(300) NOT NULL,
    acceptance_criteria TEXT,
    status              SMALLINT     NOT NULL DEFAULT 1,
    chapter             VARCHAR(100),
    created_by          BIGINT,
    created_at          TIMESTAMP    NOT NULL DEFAULT now(),
    updated_at          TIMESTAMP    NOT NULL DEFAULT now(),
    CONSTRAINT ck_requirement_source CHECK (source IN (1, 2, 3)),
    CONSTRAINT ck_requirement_status CHECK (status IN (1, 2, 3))
);
CREATE INDEX IF NOT EXISTS idx_requirement_project_status ON tp_requirement (project_id, status);
COMMENT ON TABLE  tp_requirement IS '需求点（覆盖矩阵行基础）';
COMMENT ON COLUMN tp_requirement.source IS '1=Jira 2=文档提取(F2) 3=手工';

-- ---------------------------------------------------------------------
-- ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS tp_test_case (
    id                  BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    case_no             VARCHAR(40)  NOT NULL UNIQUE,
    project_id          BIGINT       NOT NULL REFERENCES tp_project(id),
    title               VARCHAR(300),
    precondition        TEXT,
    expected_result     TEXT,
    priority            SMALLINT     NOT NULL DEFAULT 1,    -- 0=P0 1=P1 2=P2
    confidence          SMALLINT     NOT NULL DEFAULT 2,
    end_type            VARCHAR(10)  NOT NULL DEFAULT 'web',-- web/mobile/pos/multi
    status              SMALLINT     NOT NULL DEFAULT 1,
    version             INTEGER      NOT NULL DEFAULT 1,
    assignee_id         BIGINT,
    source              SMALLINT     NOT NULL DEFAULT 1,
    source_ref          VARCHAR(100),
    template_modified   SMALLINT     NOT NULL DEFAULT 0,
    last_exec_result    SMALLINT,
    last_exec_time      TIMESTAMP,
    review_fail_cnt     INTEGER      NOT NULL DEFAULT 0,
    steps_text          TEXT,
    deleted             SMALLINT     NOT NULL DEFAULT 0,
    created_by          BIGINT,
    created_at          TIMESTAMP    NOT NULL DEFAULT now(),
    updated_at          TIMESTAMP    NOT NULL DEFAULT now(),
    CONSTRAINT ck_test_case_priority   CHECK (priority IN (0, 1, 2)),
    CONSTRAINT ck_test_case_confidence CHECK (confidence IN (1, 2, 3)),
    CONSTRAINT ck_test_case_status     CHECK (status BETWEEN 1 AND 9),
    CONSTRAINT ck_test_case_deleted    CHECK (deleted IN (0, 1))
);
CREATE INDEX IF NOT EXISTS idx_test_case_project_status ON tp_test_case (project_id, status);
CREATE INDEX IF NOT EXISTS idx_test_case_status        ON tp_test_case (status);
CREATE INDEX IF NOT EXISTS idx_test_case_confidence    ON tp_test_case (confidence);
CREATE INDEX IF NOT EXISTS idx_test_case_assignee      ON tp_test_case (assignee_id) WHERE assignee_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_test_case_steps_trgm ON tp_test_case USING GIN (steps_text gin_trgm_ops);
COMMENT ON TABLE  tp_test_case IS '用例（核心）';
COMMENT ON COLUMN tp_test_case.status IS '9 态：1待评审 2评审中 3已通过 4需修改 5已拒绝 6执行中 7执行失败 8回归失败 9已归档';
COMMENT ON COLUMN tp_test_case.confidence IS 'AI 自评置信度：1=高 2=中 3=低（质量门）';

-- ---------------------------------------------------------------------
-- ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS tp_case_step (
    id          BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    case_id     BIGINT      NOT NULL REFERENCES tp_test_case(id),
    case_version INTEGER    NOT NULL DEFAULT 1,
    step_no     INTEGER     NOT NULL,
    description VARCHAR(500) NOT NULL,
    is_assert   SMALLINT    NOT NULL DEFAULT 0,
    created_at  TIMESTAMP   NOT NULL DEFAULT now(),
    updated_at  TIMESTAMP   NOT NULL DEFAULT now(),
    CONSTRAINT uq_case_step UNIQUE (case_id, case_version, step_no),
    CONSTRAINT ck_case_step_assert CHECK (is_assert IN (0, 1))
);
COMMENT ON TABLE  tp_case_step IS '用例步骤';

-- ---------------------------------------------------------------------
-- ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS tp_script (
    id                BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    case_id           BIGINT      NOT NULL UNIQUE REFERENCES tp_test_case(id),
    schema_version    VARCHAR(8)  NOT NULL DEFAULT 'v1',
    action_json       JSONB,
    status            SMALLINT    NOT NULL DEFAULT 1,
    generated_by      SMALLINT    NOT NULL DEFAULT 1,
    last_trial_result SMALLINT,
    version           INTEGER     NOT NULL DEFAULT 1,
    created_at        TIMESTAMP   NOT NULL DEFAULT now(),
    updated_at        TIMESTAMP   NOT NULL DEFAULT now(),
    CONSTRAINT ck_script_status CHECK (status IN (1, 2, 3)),
    CONSTRAINT ck_script_generated_by CHECK (generated_by IN (1, 2, 3))
);
COMMENT ON TABLE  tp_script IS '脚本（动作 JSON，与用例 1:1）';
COMMENT ON COLUMN tp_script.status IS '1=可用 2=待更新（编辑后失效） 3=生成中';

-- ---------------------------------------------------------------------
-- ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS tp_audit_log (
    id          BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    operator_id BIGINT,
    project_id  BIGINT,
    object_type VARCHAR(50)  NOT NULL,
    object_id   VARCHAR(64)  NOT NULL,
    action      VARCHAR(50)  NOT NULL,
    before_json JSONB,
    after_json  JSONB,
    prev_hash   CHAR(64)     NOT NULL DEFAULT '',
    cur_hash    CHAR(64)     NOT NULL,
    created_at  TIMESTAMP    NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_audit_log_operator ON tp_audit_log (operator_id, created_at);
CREATE INDEX IF NOT EXISTS idx_audit_log_object   ON tp_audit_log (project_id, object_type, object_id);
COMMENT ON TABLE tp_audit_log IS '审计日志：只追加，禁止 UPDATE/DELETE（DB trigger 强制）';

CREATE OR REPLACE FUNCTION tp_audit_log_no_modify() RETURNS trigger AS $$
BEGIN
    RAISE EXCEPTION 'tp_audit_log is append-only: UPDATE/DELETE forbidden (operator_id=%, action=%)',
        OLD.operator_id, OLD.action;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_audit_log_append_only ON tp_audit_log;
CREATE TRIGGER trg_audit_log_append_only
    BEFORE UPDATE OR DELETE ON tp_audit_log
    FOR EACH ROW EXECUTE FUNCTION tp_audit_log_no_modify();

-- ---------------------------------------------------------------------
-- ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS tp_ai_call_log (
    id                BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    project_id        BIGINT,
    operator_id       BIGINT,
    provider          VARCHAR(30)  NOT NULL,
    model             VARCHAR(50)  NOT NULL,
    function          VARCHAR(50)  NOT NULL,
    prompt_tokens     INTEGER      NOT NULL DEFAULT 0,
    completion_tokens INTEGER      NOT NULL DEFAULT 0,
    cost              DECIMAL(10,4) NOT NULL DEFAULT 0,
    latency_ms        INTEGER      NOT NULL DEFAULT 0,
    created_at        TIMESTAMP    NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_ai_call_log_project ON tp_ai_call_log (project_id, created_at);
COMMENT ON TABLE tp_ai_call_log IS 'AI 调用记录（Token 成本，E3 预算依据）';

-- =====================================================================
-- =====================================================================

-- ################ V2__auth_local.sql ################
-- ============================================================
-- ============================================================

CREATE TABLE IF NOT EXISTS tp_user (
    id            BIGSERIAL PRIMARY KEY,
    username      VARCHAR(50)  NOT NULL,
    password_hash VARCHAR(100),
    display_name  VARCHAR(100),
    email         VARCHAR(100),
    phone         VARCHAR(20),
    role          SMALLINT     NOT NULL DEFAULT 1,
    status        SMALLINT     NOT NULL DEFAULT 1,
    deleted       SMALLINT     NOT NULL DEFAULT 0,
    created_by    BIGINT,
    created_at    TIMESTAMP    NOT NULL DEFAULT now(),
    updated_at    TIMESTAMP    NOT NULL DEFAULT now()
);

COMMENT ON TABLE tp_user IS '本地用户（认证双模式新增；SSO 模式用户由认证中心同步，password_hash 可空）';
COMMENT ON COLUMN tp_user.role IS '1=测试人员 2=测试负责人 3=开发人员 4=系统管理员';
COMMENT ON COLUMN tp_user.status IS '1=启用 0=停用';
COMMENT ON COLUMN tp_user.deleted IS '0=正常 1=软删（列表/登录不可见，历史引用保留）';

CREATE UNIQUE INDEX IF NOT EXISTS uk_tp_user_username ON tp_user (username) WHERE deleted = 0;
CREATE INDEX IF NOT EXISTS idx_tp_user_role ON tp_user (role) WHERE deleted = 0;
CREATE INDEX IF NOT EXISTS idx_tp_user_status ON tp_user (status) WHERE deleted = 0;

-- ################ V3__review_log.sql ################
-- ============================================================
-- ============================================================

CREATE TABLE IF NOT EXISTS tp_review_log (
    id         BIGSERIAL PRIMARY KEY,
    case_id    BIGINT      NOT NULL REFERENCES tp_test_case(id),
    user_id    BIGINT      NOT NULL,
    action     VARCHAR(20) NOT NULL,
    remark     VARCHAR(500),
    created_at TIMESTAMP   NOT NULL DEFAULT now()
);

COMMENT ON TABLE  tp_review_log IS '用例评审记录（评审留痕，PRD 4.2.2）';
COMMENT ON COLUMN tp_review_log.action IS '动作：通过/需修改/拒绝/编辑/克隆/回滚';
COMMENT ON COLUMN tp_review_log.remark IS '评审意见（need_change/reject 必填，review.remark-required 配置化）';

CREATE INDEX IF NOT EXISTS idx_review_log_case ON tp_review_log (case_id, id DESC);
CREATE INDEX IF NOT EXISTS idx_review_log_user ON tp_review_log (user_id);

-- ################ V4__case_requirement.sql ################
-- ---------------------------------------------------------------------
--   docker exec testpike-postgres psql -U testpike -d testpike -f /dev/stdin < db/migration/V4__case_requirement.sql
-- ---------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS tp_case_requirement (
    id             BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    case_id        BIGINT NOT NULL REFERENCES tp_test_case(id),
    requirement_id BIGINT NOT NULL REFERENCES tp_requirement(id),
    created_by     BIGINT,
    created_at     TIMESTAMP NOT NULL DEFAULT now(),
    CONSTRAINT uk_case_requirement UNIQUE (case_id, requirement_id)
);

CREATE INDEX IF NOT EXISTS idx_case_req_requirement ON tp_case_requirement (requirement_id);
COMMENT ON TABLE  tp_case_requirement IS '用例-需求点多对多（覆盖矩阵依据）';
COMMENT ON COLUMN tp_case_requirement.case_id IS '用例 ID（H1：同项目校验在应用层）';
COMMENT ON COLUMN tp_case_requirement.requirement_id IS '需求点 ID';

-- ################ V5__ai_task_notification.sql ################
-- ---------------------------------------------------------------------
--   docker exec testpike-postgres psql -U testpike -d testpike -f /dev/stdin < db/migration/V5__ai_task_notification.sql
-- ---------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS tp_ai_task (
    id               BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    project_id       BIGINT NOT NULL,
    operator_id      BIGINT NOT NULL,
    task_type        SMALLINT NOT NULL DEFAULT 1,
    status           SMALLINT NOT NULL DEFAULT 1,   -- 1=pending 2=running 3=done 4=failed
    requirement_text TEXT,
    requirement_id   BIGINT,
    case_id          BIGINT,
    script_id        BIGINT,
    error_code       VARCHAR(30),
    error_msg        VARCHAR(500),
    retry_cnt        INT NOT NULL DEFAULT 0,
    created_at       TIMESTAMP NOT NULL DEFAULT now(),
    updated_at       TIMESTAMP NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_ai_task_project ON tp_ai_task (project_id, created_at);
CREATE INDEX IF NOT EXISTS idx_ai_task_operator ON tp_ai_task (operator_id, created_at);
COMMENT ON TABLE  tp_ai_task IS 'AI 生成任务（异步任务状态回写）';
COMMENT ON COLUMN tp_ai_task.status IS '1=pending 2=running 3=done 4=failed';
COMMENT ON COLUMN tp_ai_task.error_code IS 'MODEL_TIMEOUT/FORMAT_ERROR/SERVICE_ERROR';

CREATE TABLE IF NOT EXISTS tp_notification (
    id         BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    user_id    BIGINT NOT NULL,
    project_id BIGINT,
    event_type VARCHAR(50) NOT NULL,
    channel    VARCHAR(20) NOT NULL DEFAULT '站内',
    title      VARCHAR(200) NOT NULL,
    content    TEXT,
    card_json  JSONB,
    status     SMALLINT NOT NULL DEFAULT 1,
    retry_cnt  INT NOT NULL DEFAULT 0,
    dedup_key  VARCHAR(100),
    read_flag  SMALLINT NOT NULL DEFAULT 0,
    created_at TIMESTAMP NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_notification_user ON tp_notification (user_id, read_flag, created_at);
COMMENT ON TABLE tp_notification IS '站内信（生成失败/完成通知；07 通知中心设计）';
COMMENT ON COLUMN tp_notification.status IS '1=待发 2=已发 3=失败';
COMMENT ON COLUMN tp_notification.read_flag IS '0=未读 1=已读';

-- ################ V6__executor.sql ################

CREATE TABLE IF NOT EXISTS tp_executor (
    id              BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    name            VARCHAR(50)  NOT NULL,
    group_ids       VARCHAR(200),
    env_ids         VARCHAR(200),
    end_types       VARCHAR(100)  DEFAULT 'web',
    browsers        VARCHAR(100)  DEFAULT 'chromium',
    capacity        INT           NOT NULL DEFAULT 2,
    running_cnt     INT           NOT NULL DEFAULT 0,
    status          SMALLINT      NOT NULL DEFAULT 1,
    version         VARCHAR(30),
    last_heartbeat  TIMESTAMP,
    created_at      TIMESTAMP     NOT NULL DEFAULT now(),
    updated_at      TIMESTAMP     NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_executor_status ON tp_executor (status);

CREATE TABLE IF NOT EXISTS tp_exec_task (
    id               BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    project_id       BIGINT       NOT NULL,
    case_id          BIGINT       NOT NULL,
    batch_id         BIGINT,
    executor_id      BIGINT,
    status           SMALLINT     NOT NULL DEFAULT 1,
    claim_token      VARCHAR(64),
    schema_version   VARCHAR(10),
    action_json      TEXT,
    env_base_url     VARCHAR(500),
    error_type       SMALLINT,
    error_detail     VARCHAR(1000),
    steps_timeline   JSONB,
    screenshots_json JSONB,
    video_key        VARCHAR(200),
    duration_ms      INT,
    started_at       TIMESTAMP,
    finished_at      TIMESTAMP,
    created_at       TIMESTAMP     NOT NULL DEFAULT now(),
    updated_at       TIMESTAMP     NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_exec_task_status ON tp_exec_task (status, created_at);
CREATE INDEX IF NOT EXISTS idx_exec_task_case ON tp_exec_task (case_id);

-- ################ V7__env_type_v4.sql ################
-- =====================================================================
--
-- =====================================================================

ALTER TABLE tp_project_env DROP CONSTRAINT IF EXISTS ck_project_env_type;
ALTER TABLE tp_project_env ADD CONSTRAINT ck_project_env_type
    CHECK (env_type = ANY (ARRAY[1, 2, 3, 4]));

ALTER TABLE tp_project_env DROP CONSTRAINT IF EXISTS uq_project_env_type;
ALTER TABLE tp_project_env ADD CONSTRAINT uq_project_env_type UNIQUE (project_id, env_type);


-- ################ V8__case_defect.sql ################
-- =====================================================================
-- =====================================================================
CREATE TABLE IF NOT EXISTS tp_case_defect (
    id            BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    case_id       BIGINT       NOT NULL REFERENCES tp_test_case(id),
    defect_key    VARCHAR(50)  NOT NULL,
    defect_status VARCHAR(20)  NOT NULL DEFAULT 'open',
    status        SMALLINT     NOT NULL DEFAULT 1,
    version       INTEGER      NOT NULL DEFAULT 1,
    created_by    BIGINT,
    created_at    TIMESTAMP    NOT NULL DEFAULT now(),
    updated_at    TIMESTAMP    NOT NULL DEFAULT now(),
    CONSTRAINT uq_defect_rel UNIQUE (case_id, defect_key),
    CONSTRAINT ck_defect_rel_status CHECK (status IN (1, 2)),
    CONSTRAINT ck_defect_rel_defect_status CHECK (defect_status IN ('open', 'in_progress', 'closed'))
);
CREATE INDEX IF NOT EXISTS idx_defect_rel_case ON tp_case_defect (case_id);
CREATE INDEX IF NOT EXISTS idx_defect_rel_key  ON tp_case_defect (defect_key);
COMMENT ON TABLE  tp_case_defect IS '用例-缺陷关联（J2 缺陷闭环）';
COMMENT ON COLUMN tp_case_defect.defect_status IS 'Jira 缺陷状态回填：open/in_progress/closed（Jira 自动同步留 M2）';
COMMENT ON COLUMN tp_case_defect.status IS '闭环状态：1开启 2已关闭（关闭→DEFECT_CLOSED 事件重跑提示）';

-- ################ V9__export_task.sql ################
-- ============================================================
