CREATE TABLE IF NOT EXISTS tp_explore_step (
    id               BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    session_id       BIGINT   NOT NULL REFERENCES tp_explore_session(id),
    seq              INT      NOT NULL,
