COMMENT ON COLUMN tp_defect.occurrence_count IS '同签名累计复现次数（首建=1，追评+1，V3/T232）';

CREATE TABLE IF NOT EXISTS tp_comment (
    id         BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
