CREATE INDEX IF NOT EXISTS idx_comment_host ON tp_comment (host_type, host_id, id);

COMMENT ON TABLE tp_comment IS '多态评论表（V14 宿主面最小建：T232 自动追评 + T240 人工评论扩展复用）';
