-- ################ V145__appauto_engine_table.sql ################

CREATE TABLE IF NOT EXISTS tp_appauto_engine (
    id                   BIGSERIAL    PRIMARY KEY,
    code                 VARCHAR(64)  NOT NULL,
    name                 VARCHAR(200) NOT NULL,
    platform_codes       JSONB        NOT NULL DEFAULT '[]'::jsonb,
    device_kind_codes    JSONB        NOT NULL DEFAULT '[]'::jsonb,
    default_priority     INT          NOT NULL DEFAULT 100,
    runtime_type         VARCHAR(20)  NOT NULL,
    runtime_version_req  JSONB        NOT NULL DEFAULT '{}'::jsonb,
    capabilities         JSONB        NOT NULL DEFAULT '{}'::jsonb,
    driver_requirements  JSONB        NOT NULL DEFAULT '[]'::jsonb,
    env_check_spec       JSONB        NOT NULL DEFAULT '[]'::jsonb,
    status               SMALLINT     NOT NULL DEFAULT 1,
    install_doc_url      VARCHAR(500),
    license              VARCHAR(100),
    created_at           TIMESTAMP    NOT NULL DEFAULT now(),
    updated_at           TIMESTAMP    NOT NULL DEFAULT now(),
    CONSTRAINT uq_appauto_engine_code UNIQUE (code),
    CONSTRAINT ck_appauto_engine_runtime CHECK (runtime_type IN ('PY_INPROC', 'NODE_BRIDGE', 'CLI_SUBPROC', 'WEB_DRIVER')),
    CONSTRAINT ck_appauto_engine_status CHECK (status IN (0, 1))
);

COMMENT ON TABLE tp_appauto_engine IS '引擎描述符目录（新增引擎=插行+适配器类，禁改模型/页面）';
COMMENT ON COLUMN tp_appauto_engine.capabilities IS ' IR 动词位图十六枚+特性旗（键名与 词表同源一字不差）';
COMMENT ON COLUMN tp_appauto_engine.driver_requirements IS '可读清单：依赖的 CLI/env/服务端口（二进制运行时用户自装，同 k6 定版）';
COMMENT ON COLUMN tp_appauto_engine.status IS '1=启用 0=下架/候补（下架引擎不出现在用户可选面）';

