-- ################ V149__appauto_env_profile.sql ################

CREATE TABLE IF NOT EXISTS tp_appauto_env_profile (
    id           BIGSERIAL    PRIMARY KEY,
    project_id   BIGINT       NOT NULL REFERENCES tp_project (id),
    name         VARCHAR(200) NOT NULL,
    profile_kind VARCHAR(32)  NOT NULL,
    payload      JSONB        NOT NULL DEFAULT '{}'::jsonb,
    remark       VARCHAR(500),
    created_at   TIMESTAMP    NOT NULL DEFAULT now(),
    updated_at   TIMESTAMP    NOT NULL DEFAULT now(),
    CONSTRAINT uq_appauto_env_profile_name UNIQUE (project_id, name),
    CONSTRAINT ck_appauto_env_profile_kind CHECK (profile_kind IN
        ('MP_DEVTOOLS', 'ANDROID_SDK', 'IOS_SIMULATOR', 'HARMONY_HDC'))
);

COMMENT ON TABLE tp_appauto_env_profile IS '环境档案库（机器环境项目级可复用，多用例共享改一处全生效）';
COMMENT ON COLUMN tp_appauto_env_profile.profile_kind IS '档案型白名单：MP_DEVTOOLS(微信开发者工具)/ANDROID_SDK/IOS_SIMULATOR/HARMONY_HDC（加型=扩 CHECK+服务层白名单，禁字典表）';
COMMENT ON COLUMN tp_appauto_env_profile.payload IS '机器环境事实 jsonb（键随型而异：appid/projectPath/cliPath/autoPort/sdkRoot/adbPath/simulatorUdid/hdcPath…），扩展字段走本列禁加列';
COMMENT ON COLUMN tp_appauto_env_profile.remark IS '备注（如登录态/发布渠道注意事项，- 行「登录探针」提示位消费）';

CREATE INDEX IF NOT EXISTS ix_appauto_env_profile_project
    ON tp_appauto_env_profile (project_id, profile_kind);

-- ################ V150__appauto_case_target.sql ################

ALTER TABLE tp_test_case
    ADD COLUMN IF NOT EXISTS automation_target VARCHAR(10) NULL
        CONSTRAINT ck_test_case_automation_target CHECK (
            automation_target IS NULL OR automation_target IN ('web', 'app', 'mp')),
    ADD COLUMN IF NOT EXISTS appauto_engine VARCHAR(32) NULL,
    ADD COLUMN IF NOT EXISTS appauto_env_profile_id BIGINT NULL;

COMMENT ON COLUMN tp_test_case.automation_target IS '自动化目标 web/app/mp（NULL=未挂按 web 语义；end_type 是业务端属性两列语义正交）';
COMMENT ON COLUMN tp_test_case.appauto_engine IS 'APP/MP 目标引擎编码（tp_appauto_engine.code，启用面对账在服务层）';
COMMENT ON COLUMN tp_test_case.appauto_env_profile_id IS '环境档案引用（tp_appauto_env_profile.id，项目归属+projectPath 闸在服务层单点）';

-- ################ V151__appauto_suite_target.sql ################

ALTER TABLE tp_regression_suite
    ADD COLUMN IF NOT EXISTS automation_target VARCHAR(10) NULL
        CONSTRAINT ck_regression_suite_automation_target CHECK (
            automation_target IS NULL OR automation_target IN ('web', 'app', 'mp')),
    ADD COLUMN IF NOT EXISTS appauto_engine VARCHAR(32) NULL,
    ADD COLUMN IF NOT EXISTS appauto_env_profile_id BIGINT NULL;

COMMENT ON COLUMN tp_regression_suite.automation_target IS '套件自动化目标 web/app/mp（NULL=未挂按 web 语义；同 迁移件 用例列口径）';
COMMENT ON COLUMN tp_regression_suite.appauto_engine IS 'APP/MP 目标引擎编码（tp_appauto_engine.code，启用面对账在服务层）';
COMMENT ON COLUMN tp_regression_suite.appauto_env_profile_id IS '环境档案引用（tp_appauto_env_profile.id，项目归属+projectPath 闸在服务层单点）';

-- ################ V152__help_doc_appauto_engine.sql ################
INSERT INTO tp_help_doc (domain_code, title, body_md, sort_no, version) VALUES
('X', 'APP 测试怎么跑：设备墙与引擎中心', $mdq$
## 这一页能做什么
带你走一遍 APP 自动化测试的两块管理面：在「设备墙」登记与维护手机/模拟器设备、看清谁在占用哪台、什么时候释放；在「引擎中心」了解系统支持哪些自动化引擎与平台、按需调整展示名、优先级与上下架。全程界面点选，不用手写引擎配置。

## 怎么用（按操作顺序）
1. **登记设备**：左侧菜单进「设备墙」→ 选中项目 → 点「注册设备」，填名称、序列号、设备类型（模拟器 / ADB 远程 / USB 直连）；ADB 远程设备还要填接入地址（ip:port）。序列号是项目内的唯一登记锚，登记后不可改。
2. **看占用与排队**：列表的「占用情况」列直接显示哪台设备正被哪个执行器占用、预计什么时间释放；没被占用的显示「空闲」。点行上的「占用记录」可打开流水抽屉，看到这台设备完整的占用/归还历史，包括每次归还的原因（正常完成、超时回收、人工释放等）。
3. **隔离与解禁**：设备连续失联会被自动隔离（角标变红、显示「已隔离」），此时它不再参与排队；在设备上排查后点「解除隔离」即可重新参与排队。删除占用中的设备会被拒绝，并点名当前占用者。
4. **看引擎目录**：左侧菜单进「引擎中心」，每张卡片是一个自动化引擎：支持哪些平台（Android/iOS/鸿蒙/小程序等）、什么设备形态、需要什么运行时与外部工具、动作能力清单、路由优先级和安装文档链接。引擎需要的命令行工具（如 ADB、节点运行时）需按安装文档自行安装，系统只负责调度与适配。
5. **管理引擎与平台**：有管理权限的账号可在卡片上点「管理」，修改展示名、路由优先级、安装文档链接，或把某引擎下架（停用）/恢复上架；平台目录同理可维护引导文案与上下架。下架的引擎对普通使用者立即不可选，新任务不再路由到它。

## 操作背后系统做了什么
- 设备档案按项目隔离：你只会看到自己有权限的项目的设备；互斥占用由调度侧租约统一控制，设备墙上的占用与流水是如实的展示投影，同一台设备同时只会被一个批次拿走。
- 设备在线状态与连续失联计数来自执行器的真实探活回写，页面不做猜测；预计释放时间就是当前占用的租约到期点，到期后系统自动回收并记一条「超时回收」流水。
- 引擎选择按「路由优先级」从小到大尝试，并要求执行器具备对应能力（装了什么工具、接了什么设备）；没有合格引擎时任务诚实排队等说明原因的提示，不会假装能跑。默认引擎可全局配置，配置了非法或已下架的引擎会自动回退到内置默认。
- 管理面的每次修改都会记审计（谁在什么时间改了什么），下架动作同时影响用户可选面与调度回退判定。

## 常见问题
- 占用记录里的「预计释放」到了时间设备还显示占用？——回收由后台周期任务执行，最多滞后一个回收周期；期间新任务已不会派给它。
- 引擎卡片显示「暂无在线执行器」？——说明当前没有任何在线执行器上报，先检查执行机是否开机接入，与引擎本身无关。
- 为什么不能在这页改引擎支持的动作清单？——能力清单是引擎适配矩阵的数据源，随版本发布维护，界面只提供展示，防止改出调度与实际不符的假能力。
$mdq$, 1, '2.58')
ON CONFLICT (domain_code, sort_no) DO UPDATE SET title = EXCLUDED.title, body_md = EXCLUDED.body_md, version = EXCLUDED.version, updated_at = now();

