        {"cmd": "curl -fsSL -o %TEMP%\\maestro.zip https://github.com/mobile-dev-inc/maestro/releases/download/cli-2.11.0/maestro.zip"},
        {"cmd": "tar -xf %TEMP%\\maestro.zip -C C:\\maestro"},
