-- ################ V229__mock_shell_scenario_hit_recording_aijob.sql ################
-- API Mock module, migration shell part 2 : the remaining
-- four shells — scenario definitions, hit ledger, recordings, AI jobs.
-- What this file lands and why:
--   1) tp_mock_scenario = stateful machine DECLARATIONS (states/transitions as jsonb,
--      shape frozen for M5); runtime state (session -> current state) lives in Redis
--      under K8 TTL keys, never in this table — the DB stays the definition truth,
--      Redis stays the volatile run truth;
--   2) tp_mock_hit_log = the request inspector ledger written by core from the MQ
--      batch (mock-server never writes PG directly). request_snapshot/match_trace are
--      masked BEFORE landing (PII red line: real traffic is full of it); stub_id NULL
--      = a miss row, which is exactly what "why is my mock not hitting" is answered
--      with; month-partitioning is deferred on purpose (retention sweeper starts with
-- , this shell only fixes the column truth);
--   3) tp_mock_recording = cassette boxes (proxy-recorded traffic aggregated per
--      endpoint; the cassette body goes to MinIO, this row keeps stats + reference);
--   4) tp_mock_ai_job = async AI drafting jobs (nl->stub / edge scenarios / LLM
--      fallback cache): budget_snapshot_id pins the cost account at creation time,
--      result_preview_ref keeps the "preview first, ticked-in by a human" quality
--      gate — no AI output ever enters the rule source directly.
-- Execution: manual psql (Flyway not enabled):
--   docker exec -i -e PGPASSWORD=... testpike-postgres psql -U ... -d testpike -f - < this file

CREATE TABLE IF NOT EXISTS tp_mock_scenario (
    id              BIGSERIAL    PRIMARY KEY,
    space_id        BIGINT       NOT NULL REFERENCES tp_mock_space (id),
    name            VARCHAR(80)  NOT NULL,
    definition_json JSONB        NOT NULL DEFAULT '{}',
    created_at      TIMESTAMP    NOT NULL DEFAULT now(),
    updated_at      TIMESTAMP    NOT NULL DEFAULT now(),
    CONSTRAINT uq_mock_scenario_space_name UNIQUE (space_id, name),
    CONSTRAINT ck_mock_scenario_definition CHECK (jsonb_typeof(definition_json) = 'object')
);

COMMENT ON TABLE tp_mock_scenario IS 'Stateful scenario declaration (machine definition only; runtime session->state lives in Redis with K8 TTL, never here)';
COMMENT ON COLUMN tp_mock_scenario.definition_json IS 'States/transitions declaration as jsonb (shape frozen by M5; stub rows reference it by scenario_name)';

CREATE TABLE IF NOT EXISTS tp_mock_hit_log (
    id                BIGSERIAL   PRIMARY KEY,
    space_id          BIGINT      NOT NULL,
    stub_id           BIGINT,
    request_snapshot  JSONB       NOT NULL DEFAULT '{}',
    matched           BOOLEAN     NOT NULL,
    match_trace       JSONB       NOT NULL DEFAULT '[]',
    latency_ms        INT,
    fault_applied     VARCHAR(60),
    session_id        VARCHAR(80),
    hit_at            TIMESTAMP   NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_mock_hit_space_time ON tp_mock_hit_log (space_id, hit_at DESC);

COMMENT ON TABLE tp_mock_hit_log IS 'Mock hit ledger (inspector rows; written by core from the MQ batch, mock-server never writes PG)';
COMMENT ON COLUMN tp_mock_hit_log.stub_id IS 'Matched stub; NULL = miss row (miss reasons are read from match_trace)';
COMMENT ON COLUMN tp_mock_hit_log.request_snapshot IS 'Masked request summary as jsonb (sensitive headers/body fields pass the masking pipeline BEFORE landing — PII red line)';
COMMENT ON COLUMN tp_mock_hit_log.match_trace IS 'Per-matcher verdict rows (which matcher failed and why: expected vs actual) — the inspector light-up rows';
COMMENT ON COLUMN tp_mock_hit_log.fault_applied IS 'Fault kind applied to this hit (NULL = normal response; honest annotation, reports and badges consume it)';
COMMENT ON COLUMN tp_mock_hit_log.session_id IS 'Session lane of the hit (X-TP-Mock-Session; CI parallel runs stay isolated through it)';

CREATE TABLE IF NOT EXISTS tp_mock_recording (
    id               BIGSERIAL    PRIMARY KEY,
    space_id         BIGINT       NOT NULL REFERENCES tp_mock_space (id),
    target_base_url  VARCHAR(300) NOT NULL,
    status           VARCHAR(20)  NOT NULL DEFAULT 'recording',
    summary_json     JSONB        NOT NULL DEFAULT '{}',
    cassette_ref     VARCHAR(300),
    promoted_count   INT          NOT NULL DEFAULT 0,
    created_at       TIMESTAMP    NOT NULL DEFAULT now(),
    updated_at       TIMESTAMP    NOT NULL DEFAULT now(),
    CONSTRAINT ck_mock_recording_status CHECK (status IN ('recording', 'stopped', 'promoted', 'failed'))
);

COMMENT ON TABLE tp_mock_recording IS 'Recording cassette box (proxy traffic captured behind the allowlist gate; cassette body stored in MinIO, this row keeps stats + reference)';
COMMENT ON COLUMN tp_mock_recording.summary_json IS 'Per-endpoint cluster statistics as jsonb (dedup groups, sample counts — the promotion draft source, masked first)';
COMMENT ON COLUMN tp_mock_recording.cassette_ref IS 'MinIO artifact reference of the cassette body';
COMMENT ON COLUMN tp_mock_recording.promoted_count IS 'How many stubs were promoted from this recording (traceability badge counter)';

CREATE TABLE IF NOT EXISTS tp_mock_ai_job (
    id                  BIGSERIAL    PRIMARY KEY,
    space_id            BIGINT       NOT NULL REFERENCES tp_mock_space (id),
    job_type            VARCHAR(30)  NOT NULL,
    input_json          JSONB        NOT NULL DEFAULT '{}',
    budget_snapshot_id  BIGINT,
    status              VARCHAR(20)  NOT NULL DEFAULT 'queued',
    result_preview_ref  VARCHAR(300),
    error_message       VARCHAR(500),
    created_at          TIMESTAMP    NOT NULL DEFAULT now(),
    updated_at          TIMESTAMP    NOT NULL DEFAULT now(),
    CONSTRAINT ck_mock_ai_job_type CHECK (job_type IN ('nl-stub', 'edge-scenarios', 'llm-fallback', 'record-summarize', 'spec-sync')),
    CONSTRAINT ck_mock_ai_job_status CHECK (status IN ('queued', 'running', 'preview', 'consumed', 'failed', 'cancelled'))
);
CREATE INDEX IF NOT EXISTS idx_mock_ai_job_space ON tp_mock_ai_job (space_id, status);

COMMENT ON TABLE tp_mock_ai_job IS 'Async mock AI job (every application point off by default; results only ever land as a human-ticked preview)';
COMMENT ON COLUMN tp_mock_ai_job.budget_snapshot_id IS 'Cost account pinned at creation time (budget_snapshot discipline, never settled after the fact)';
COMMENT ON COLUMN tp_mock_ai_job.result_preview_ref IS 'Preview artifact reference (draft stubs wait for human selection; AI output never writes the rule source directly)';

-- ################ V230__help_doc_mock_inspector.sql ################
-- Migration: open the API-mocking help chapter for the traffic inspector page
-- (red-line 8 doc sync; consumer = mock-inspector page help anchor openHelp('T')).
-- What this segment lands and why: domain T (API testing) previously carried a single
-- chapter, so the inspector leaf could not anchor-jump to its own explanation — a
-- domain-code jump only ever hit the first chapter. This chapter describes what the
-- inspector answers (which rule version the serving plane is live with, and why a
-- request hit or missed), matching the shipped UI one-to-one.
-- Discipline: the $mdq$ body carries zero table names / config keys / feature codes;
-- idempotent via ON CONFLICT (domain_code, sort_no) DO UPDATE.
-- Usage: docker exec -i -e PGPASSWORD=... testpike-postgres psql -U ... -d testpike -f - < this file
INSERT INTO tp_help_doc (domain_code, title, body_md, sort_no, version) VALUES
('T', '接口仿真：Mock 流量怎么看清命中与落空', $mdq$
## 这一页能做什么
流量检视回答两个问题：「数据面此刻在服务哪个版本的规则」和「每一个真实进来的请求为什么命中/落空了这条规则」。选定项目和 Mock 空间后，页面顶部是一条装载状态条，下方是实时流量账本：每行一个到达过的请求，写明方法、路径、命中结果、对上的规则名、耗时与故障注入标记；点任意一行展开请求快照与匹配轨迹。

## 怎么用
入口：左侧菜单「接口仿真 → 流量检视」。
1. 顶部选择项目，随即选择该项目下的 Mock 空间（空间在规则页创建并发布后才会出现在这里）。
2. 状态条绿=数据面正在按最新版规则对外服务；黄=有降级（新版本还没装载上、装载连续失败、或账本缓冲溢出），条上直接写明原因；红=此刻读不到数据面自检，这是如实上报，不等于规则丢了。
3. 「全部流量 / 只命中 / 只落空」三档筛选排掉噪音：排查「我的规则怎么没生效」直接切「只落空」。
4. 「实时刷新」勾选后每 2 秒拉一次新账本，取消勾选即停止轮询；离开页面自动停止。
5. 点任意一行打开右侧抽屉：请求快照（方法/路径/查询参数/请求头/请求体）+ 按规则声明序逐条判定的匹配轨迹，写明每条候选规则为什么被排除。

## 操作背后系统做了什么
- 装载状态条是现场读取数据面自检的结果，页面不缓存也不猜：读不到就明说读不到，绝不拿上一次的值冒充当前健康。
- 数据面装载新版本失败时，仍以上一次成功的版本继续对外服务（旧值不冒充新值，但也不至于停服），状态条把「连续失败几次、最近一次什么原因」原样呈现。
- 规则发布后数据面未及时装载上（状态条黄），期间进来的请求走的还是旧规则——匹配轨迹里能看到实际参与判定的候选集，不会用新规则解释旧行为。
- 账本写入走异步攒批：在途缓冲条数、是否已降级落盘、溢出丢弃条数都在状态条如实声明。丢弃只意味着账本有缺口，不意味着请求失败。
- 请求快照里的敏感内容在进入页面之前就已由管道脱敏，检视器只渲染管道给出的值，页面上不存在第二次「解开看原文」的路径。
- 空间按路由优先级排序展示；一个空间对应一个数据面实例，切换空间即切换对应的装载自检与流量账本。

## 常见问题
- 选了项目却没有空间可选？——该项目还没建 Mock 空间，去接口仿真的规则页创建并发布一个。
- 状态条一直红？——数据面此刻不可达（进程没起来或地址配置指向了别处），先确认服务在线，页面不会假装健康。
- 流量列表是空的？——这个空间最近确实没有请求到达；检视器只呈现真实到过的流量，不生成示例数据。
- 明明配了规则却显示落空？——切「只落空」并展开该行匹配轨迹，逐条看候选规则被排除的原因（路径、方法、参数匹配条件与声明顺序都会影响结论）。
- 账本说丢弃了若干条，会影响判定吗？——丢弃的是账本记录，不是请求本身；要精确统计请先降低流量或调大缓冲。
$mdq$, 2, '1.0')
ON CONFLICT (domain_code, sort_no) DO UPDATE SET title = EXCLUDED.title, body_md = EXCLUDED.body_md, version = EXCLUDED.version, updated_at = now();

-- ################ V231__mock_public_base_url.sql ################
-- Migration: seed mock.public-base-url, the one config the workbench URL card was
-- missing . The card and the copy-curl example need the
-- externally reachable address of the traffic plane (default port 18086); a
-- deployment behind a reverse proxy or a domain changes this single K8 key
-- instead of editing code anywhere. Idempotent via WHERE NOT EXISTS.
-- Usage: docker exec -i -e PGPASSWORD=... testpike-postgres psql -U ... -d testpike -f - < this file
INSERT INTO tp_sys_config (config_key, config_value, group_name, value_type, encrypt_flag, description)
SELECT 'mock.public-base-url', 'http://localhost:18086', '接口仿真', 'string', 0,
       'Mock 数据面对外访问基址：URL 卡与 curl 示例按 {本值}{mock.traffic.base-path}/{空间键} 拼装；反代/域名部署改本值为对外可达地址（K8 热更，禁硬编码）'
WHERE NOT EXISTS (SELECT 1 FROM tp_sys_config WHERE config_key = 'mock.public-base-url');

-- ################ V232__mock_recording_control_plane.sql ################
-- Migration: recording control plane columns .
-- tp_mock_space gains the bound proxy target: start() writes it after the
-- allowlist gate so 's forwarder reads one single source per space
-- (NULL = this space never proxied). tp_mock_recording gains explicit
-- started_at/ended_at stamps: created_at is row-insert noise, the control
-- plane must carry the honest open/seal moments of a cassette box.
-- The (space_id, id DESC) index serves the newest-box-first list page.
-- No new tp_sys_config keys here (mock.proxy.allowlist was seeded by V228).
-- Usage: docker exec -i -e PGPASSWORD=... testpike-postgres psql -U ... -d testpike -f - < this file

ALTER TABLE tp_mock_space ADD COLUMN IF NOT EXISTS proxy_target_url VARCHAR(300);
COMMENT ON COLUMN tp_mock_space.proxy_target_url IS 'Bound proxy target base URL written by the recording start gate (NULL = never proxied); the proxy forwarder consumes this single source';

ALTER TABLE tp_mock_recording ADD COLUMN IF NOT EXISTS started_at TIMESTAMP;
ALTER TABLE tp_mock_recording ADD COLUMN IF NOT EXISTS ended_at TIMESTAMP;
COMMENT ON COLUMN tp_mock_recording.started_at IS 'Box-open stamp written by the control plane (distinct from created_at row-insert time)';
COMMENT ON COLUMN tp_mock_recording.ended_at IS 'Box-seal stamp written when the recording stops (NULL while open)';

CREATE INDEX IF NOT EXISTS idx_mock_recording_space ON tp_mock_recording (space_id, id DESC);

-- ################ V233__mock_hit_response_snapshot.sql ################
-- Migration: response plane of the hit ledger .
-- The inspector so far only saw the request side of a mocked call; answering
-- "what did the mock actually reply" needs the served status/headers/body.
-- response_snapshot is a nullable jsonb {status,headers,body}: NULL means no
-- response facets were captured on that row (legacy rows and honest misses),
-- deliberately NOT '{}' so "absent" and "empty document" stay tellable apart.
-- No new tp_sys_config keys here (the body-truncation key ships with .
-- Usage: docker exec -i -e PGPASSWORD=... testpike-postgres psql -U ... -d testpike -f - < this file

ALTER TABLE tp_mock_hit_log ADD COLUMN IF NOT EXISTS response_snapshot JSONB;
COMMENT ON COLUMN tp_mock_hit_log.response_snapshot IS 'Masked stub response as jsonb {status,headers,body} (sensitive response headers star-valued and body masked BEFORE leaving the plane — same PII red line as request_snapshot; NULL = no response captured)';

-- ################ V234__mock_recording_frame_keys.sql ################
-- Migration: recording frame plane seeds .
-- mock.hit.max-body-chars is the single body-size bound every mock payload
-- shares (hit ledger request/response facets and recording frame bodies alike
-- — one MockBodyTruncator gate, no forked semantics): oversized bodies land
-- capped with a size-honest truncation tail note so a payload deluge never
-- bloats the inspector tables. mock.recording.hold-ttl-seconds keeps the
-- per-box Redis frame hold alive: an abandoned open box self-expires instead
-- of leaking staged frames forever.
-- Idempotent via WHERE NOT EXISTS.
-- Usage: docker exec -i -e PGPASSWORD=... testpike-postgres psql -U ... -d testpike -f - < this file
INSERT INTO tp_sys_config (config_key, config_value, group_name, value_type, encrypt_flag, description)
SELECT 'mock.hit.max-body-chars', '8192', '接口仿真', 'number', 0,
       'Mock 流量体截断上限（字符数）：命中流水请求/响应体与录制帧体同一闸门超限保头部并追加原长度标注（K8 热更，禁硬编码）'
WHERE NOT EXISTS (SELECT 1 FROM tp_sys_config WHERE config_key = 'mock.hit.max-body-chars');

INSERT INTO tp_sys_config (config_key, config_value, group_name, value_type, encrypt_flag, description)
SELECT 'mock.recording.hold-ttl-seconds', '86400', '接口仿真', 'number', 0,
       '录制盒帧暂存窗（秒）：Redis 暂存键保活时长，开盒弃置不封时到期自清（K8 热更）'
WHERE NOT EXISTS (SELECT 1 FROM tp_sys_config WHERE config_key = 'mock.recording.hold-ttl-seconds');

-- ################ V235__mock_space_chaos_percent.sql ################
-- Migration: mock space chaos dial column .
-- chaos_percent is the space-level fault-injection dial: 0-100 percent of
-- served requests the traffic plane answers with a plain 503 (retry-storm /
-- frontend resilience drill). It is TRAFFIC CONTENT — the snapshot pin folds
-- it in, so moving the dial swaps the loader's served generation instead of
-- drifting silently under live traffic mid-pin.
-- The range is guarded twice on purpose: the save-chain validator gives the
-- plain-word refusal, this CHECK is the last honest word at the row level
-- against any side-door write.
ALTER TABLE tp_mock_space ADD COLUMN IF NOT EXISTS chaos_percent SMALLINT NOT NULL DEFAULT 0;
ALTER TABLE tp_mock_space DROP CONSTRAINT IF EXISTS ck_mock_space_chaos_percent;
ALTER TABLE tp_mock_space ADD CONSTRAINT ck_mock_space_chaos_percent CHECK (chaos_percent BETWEEN 0 AND 100);
COMMENT ON COLUMN tp_mock_space.chaos_percent IS 'Space-level chaos dial 0-100 (percent of served requests answered 503 by the fault kernel); traffic content - folded into the snapshot pin';

-- ################ V236__mock_space_expires_at.sql ################
-- Migration: mock space expiry column .
-- expires_at is set when a CI door creates a throwaway space with a TTL:
-- short-lived pipeline sandboxes must not leak into the routing plane
-- forever. NULL = never expires (every UI-created space).
-- The column is NOT traffic content — the snapshot pin ignores it, because
-- expiry changes the space's life span, not what served requests see. The
-- expiry sweep (retire + notify or auto-retire) lands in next to
-- the SchedulerJobCatalog entry.
ALTER TABLE tp_mock_space ADD COLUMN IF NOT EXISTS expires_at TIMESTAMP;
COMMENT ON COLUMN tp_mock_space.expires_at IS 'CI-created space expiry instant (NULL = never expires); swept by the scheduled expiry job, not a traffic-content field';

-- ################ V237__case_suite_mock_binding.sql ################
-- Migration: declarative mock bindings for test cases and regression suites .
-- mock_space_id names a published mock space whose rules stand in for the real
-- environment during execution: NULL = run against the real system (default, zero
-- drift for all existing rows). The executor only rewrites base_url (HTTP cases) or
-- installs playwright route interception (web cases) when a space is bound — the
-- binding is a declarative scope, never an implicit environment change.
-- While a space is referenced by any live case or suite, the retire/delete edge is
-- blocked with a clickable reference list (ruling C-4); MockSpaceReferenceGate is the
-- single source of that question, so both the manual transition and the expiry sweep
-- see the new reasons without touching their own code.
ALTER TABLE tp_test_case ADD COLUMN IF NOT EXISTS mock_space_id BIGINT REFERENCES tp_mock_space (id);
ALTER TABLE tp_regression_suite ADD COLUMN IF NOT EXISTS mock_space_id BIGINT REFERENCES tp_mock_space (id);
CREATE INDEX IF NOT EXISTS idx_test_case_mock_space ON tp_test_case (mock_space_id) WHERE mock_space_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_regression_suite_mock_space ON tp_regression_suite (mock_space_id) WHERE mock_space_id IS NOT NULL;
COMMENT ON COLUMN tp_test_case.mock_space_id IS 'Published mock space this case runs against (NULL = real environment); blocks space retire while bound (C-4)';
COMMENT ON COLUMN tp_regression_suite.mock_space_id IS 'Published mock space this suite runs against (NULL = real environment); blocks space retire while bound (C-4)';

-- ################ V238__batch_report_mock_task_cnt.sql ################
-- V238: mock-serving count on the batch report snapshot .
-- tp_batch_report is a point-in-time snapshot row; the mock-task count is captured
-- at finalize time (never recomputed on the read path) so the completion notice and
-- the report page read the same row. A task counts as mock-served when its
-- result_ext carries a non-empty "mockNotes" audit bucket written by the executor.
ALTER TABLE tp_batch_report
    ADD COLUMN IF NOT EXISTS mock_task_cnt INT NOT NULL DEFAULT 0;

COMMENT ON COLUMN tp_batch_report.mock_task_cnt IS 'Tasks in this batch whose result evidence carries a non-empty mockNotes bucket (snapshot at finalize; 0 for pre-V238 rows)';

-- ################ V239__mock_ai_job_switches_budget.sql ################
-- AG batch : AI mock-generation job switches + creation-time budget pin.
--
-- Why this file exists:
--   1) tp_mock_ai_job (shell created in V229) gains a budget_snapshot JSONB column.
--      The cost account is pinned as the full snapshot body at job-creation time
--      (explore V57 precedent: consumers must never re-read the global keys later,
--      otherwise a hot config change would silently re-price an in-flight job).
--      The legacy budget_snapshot_id BIGINT column stays untouched — it is a
--      reserved reference slot, not the source of truth for this batch.
--   2) Three per-application-point sub-switches (feature plan §7): the master
--      gate ai.mock.enabled (seeded by V228) is ANDed with one switch per point.
--      Every switch defaults to '0' (off) — AI drafting never runs until an
--      operator opens both gates. M10 points (llm-fallback / record-summarize)
--      deliberately have no keys yet: their job types are refused outright this
--      period, so a switch would promise a path that does not exist.
--
-- Idempotent via ON CONFLICT DO NOTHING (re-run safe).
-- Usage: docker exec -i -e PGPASSWORD=... testpike-postgres psql -U ... -d testpike -f - < this file

ALTER TABLE tp_mock_ai_job ADD COLUMN IF NOT EXISTS budget_snapshot JSONB;

COMMENT ON COLUMN tp_mock_ai_job.budget_snapshot IS
    'Cost account pinned at creation time as the full snapshot body (estimate inputs + quotas); consumers read this column, never the live global keys';

INSERT INTO tp_sys_config (config_key, config_value, group_name, value_type, encrypt_flag, description)
VALUES
    ('ai.mock.nl-stub', '1', 'AI 配置', 'bool', 0,
     'A-1 自然语言建 Mock 分开关：默认关；与总闸 ai.mock.enabled 做与运算，任一关则拒绝创建草稿任务（报错说明原因+审计留痕）'),
    ('ai.mock.edge-scenarios', '1', 'AI 配置', 'bool', 0,
