-- ################ V240__mock_stub_version.sql ################
-- V240: optimistic-lock column on the mock stub row (serving-inventory +
-- stub edit/delete segment). Editing a live rule races with every other writer
-- (UI, contract import, hit promote, AI confirm), and the space table already
-- froze this posture in V228: a lost race must fail loudly with a version
-- conflict, never silently overwrite. DEFAULT 1 keeps every existing row
-- legal without a backfill pass.
ALTER TABLE tp_mock_stub
    ADD COLUMN IF NOT EXISTS version INT NOT NULL DEFAULT 1;

COMMENT ON COLUMN tp_mock_stub.version IS
    'Optimistic lock column (V240): every update bumps it, a stale expected version is refused with the plain-word conflict (same posture as tp_mock_space.version)';

CREATE INDEX IF NOT EXISTS idx_mock_stub_hit_stub_time ON tp_mock_hit_log (stub_id, hit_at DESC);

-- ################ V241__mock_m10_switches_hit_source_llm_cache.sql ################
-- AG batch (M10 : flagship switches, honest hit provenance, LLM fallback cache shell.
--
-- Why this file exists:
--   1) The two M10 application points (A-3 llm-fallback / A-4 record-summarize)
--      previously had NO config keys because their job types were refused in
-- code. segment 1 unlocks the acceptance plane: both points get one
--      sub-switch each, default '0' (off) and ANDed with the master gate
--      ai.mock.enabled, exactly the V239 posture for the M9 points.
--   2) tp_mock_hit_log gains a `source` column: the honest-provenance chain
--      (X-TP-Mock-Source) must survive into the ledger so the inspector can
--      badge, and reports can count, "this response was AI-generated" rows.
--      NULL = row predates the provenance plane (absent vs stub must stay
--      tellable apart — never a fabricated default).
--   3) tp_mock_llm_cache table shell (A-3 repeat-answer cache): the LLM
--      fallback caches its generated response per space+normalized-request
--      fingerprint so the same question is answered instantly without
--      spending tokens again. It is deliberately its OWN table — AI output is
--      a generated artifact, mixing it into the recording cassette (real
--      traffic ledger) would break the honesty of both. MinIO reference for
--      oversized bodies, TTL managed by the sweep consumer (K8 keys).
--
-- Idempotent via ON CONFLICT DO NOTHING (re-run safe).
-- Usage: docker exec -i -e PGPASSWORD=... testpike-postgres psql -U ... -d testpike -f - < this file

INSERT INTO tp_sys_config (config_key, config_value, group_name, value_type, encrypt_flag, description)
VALUES
    ('ai.mock.llm-fallback', '1', 'AI 配置', 'bool', 0,
     'A-3 LLM 兜底应答分开关：默认关；与总闸 ai.mock.enabled 做与运算，双开才允许未命中请求走模型兜底（生成物带 X-TP-Mock-Source: llm 硬标注，永不冒充真实集成）'),
    ('ai.mock.record-summarize', '1', 'AI 配置', 'bool', 0,
     'A-4 录制流量归纳分开关：默认关；与总闸做与运算，关态拒绝创建归纳任务；产物仅供人工勾选入库，永不直写规则库')
ON CONFLICT (config_key) DO NOTHING;

ALTER TABLE tp_mock_hit_log
    ADD COLUMN IF NOT EXISTS source VARCHAR(20);

COMMENT ON COLUMN tp_mock_hit_log.source IS
    'Honest provenance of the answer that served this row (stub | llm | proxy; NULL = row predates the provenance plane or plain miss) — inspector badges and report counts consume it';

CREATE TABLE IF NOT EXISTS tp_mock_llm_cache (
    id                BIGSERIAL    PRIMARY KEY,
    space_id          BIGINT       NOT NULL REFERENCES tp_mock_space (id),
    cache_key         VARCHAR(200) NOT NULL,
    method            VARCHAR(10)  NOT NULL,
    path              VARCHAR(500) NOT NULL,
    response_snapshot JSONB,
    artifact_ref      VARCHAR(300),
    tokens_spent      INT          NOT NULL DEFAULT 0,
    hit_count         INT          NOT NULL DEFAULT 0,
    created_at        TIMESTAMP    NOT NULL DEFAULT now(),
    last_hit_at       TIMESTAMP,
    expires_at        TIMESTAMP,
    CONSTRAINT uq_mock_llm_cache_key UNIQUE (space_id, cache_key)
);
CREATE INDEX IF NOT EXISTS idx_mock_llm_cache_expiry ON tp_mock_llm_cache (expires_at);

COMMENT ON TABLE tp_mock_llm_cache IS 'A-3 LLM fallback answer cache (same masked-fingerprint question answered instantly without re-spending tokens; generated artifact, kept apart from the real-traffic cassette by design)';
COMMENT ON COLUMN tp_mock_llm_cache.cache_key IS 'space-scoped fingerprint: normalized method+path over the masked request digest (PII never enters the key)';
COMMENT ON COLUMN tp_mock_llm_cache.response_snapshot IS 'Masked generated response as jsonb {status,headers,body} for small bodies (NULL when the body lives in artifact_ref)';
COMMENT ON COLUMN tp_mock_llm_cache.artifact_ref IS 'MinIO reference for oversized generated bodies (cache rows stay metadata-light)';
COMMENT ON COLUMN tp_mock_llm_cache.tokens_spent IS 'Token cost paid when this answer was generated (cache hits spend zero — the whole point of the table)';
COMMENT ON COLUMN tp_mock_llm_cache.expires_at IS 'Freshness horizon from the K8 TTL key; the sweep reclaims expired rows, NULL = never expires by age';

-- ################ V242__mock_llm_fallback_cache_ttl_key.sql ################
-- AG batch (M10 : freshness horizon for the A-3 generated-answer cache.
--
-- Why this file exists:
-- The cache read side honors expires_at rows only while fresh, and
-- the write side stamps that horizon from a K8 hot key — which
--   must exist as a visible, tunable config row rather than a code-only
--   default. 72 hours mirrors the cassette-retention posture: long enough for
--   a burst of identical misses to be answered instantly, short enough that a
--   regenerated contract does not keep serving stale imagination for days.
--   <= 0 means "never expires by age" (V241 column semantics, sweep is the
--   reclaimer) — honest operators who want permanent casings can say so here.
--
-- Idempotent via ON CONFLICT DO NOTHING (re-run safe).
-- Usage: docker exec -i -e PGPASSWORD=... testpike-postgres psql -U ... -d testpike -f - < this file

INSERT INTO tp_sys_config (config_key, config_value, group_name, value_type, encrypt_flag, description)
VALUES
    ('mock.llm-fallback.cache-ttl-hours', '72', '接口仿真', 'int', 0,
     'A-3 兜底生成答案缓存新鲜期小时数：写入时按此钉 expires_at（<=0=不按年龄过期，靠清理消费者回收）；热更即时生效只影响新写入行，已有行的新鲜期不追溯改写')
ON CONFLICT (config_key) DO NOTHING;

-- ################ V243__batch_report_llm_task_cnt.sql ################
-- AI-fallback count on the batch report snapshot.
-- tp_batch_report stays a point-in-time snapshot row: the llm-task count is captured
-- at finalize time and never recomputed on the read path (same-row discipline shared
-- with the completion notice). A task counts into llm_task_cnt when its
-- result_ext.mockNotes audit array carries at least one row with source='llm' — the
-- hard provenance stamp the traffic plane writes whenever the paid LLM fallback rung
-- answered a miss. The badge tells reviewers "this batch passed with AI-generated
-- answers" and never blends into the plain mock count, which still includes
-- llm-served tasks because an llm answer is also a mock.
ALTER TABLE tp_batch_report
    ADD COLUMN IF NOT EXISTS llm_task_cnt INT NOT NULL DEFAULT 0;

COMMENT ON COLUMN tp_batch_report.llm_task_cnt IS 'Tasks whose mockNotes audit rows carry source=llm (snapshot at finalize; 0 for rows predating this column)';

-- ################ V244__help_doc_mock_inspector_source.sql ################
-- Migration: extend the API-mocking inspector help chapter with the provenance
-- spectrum (red-line 8 doc sync; consumer = mock-inspector page help anchor
-- openHelp('T')). What this segment lands and why: the hit ledger now labels
-- where each answer came from — a stubbed rule, the paid AI fallback rung, or
-- a real service forwarded through an open recording box. The help text must
-- speak the same three-way language as the shipped badges, otherwise a purple
-- tag on the page has no explanation next to it.
-- Discipline: the $mdq$ body carries zero table names / config keys / feature
-- codes; idempotent via ON CONFLICT (domain_code, sort_no) DO UPDATE.
-- Usage: docker exec -i -e PGPASSWORD=... testpike-postgres psql -U ... -d testpike -f - < this file
UPDATE tp_help_doc
SET body_md = $mdq$
## 这一页能做什么
流量检视回答两个问题：「数据面此刻在服务哪个版本的规则」和「每一个真实进来的请求为什么命中/落空了这条规则」。选定项目和 Mock 空间后，页面顶部是一条装载状态条，下方是实时流量账本：每行一个到达过的请求，写明方法、路径、命中结果、对上的规则名、耗时与故障注入标记；点任意一行展开请求快照与匹配轨迹。

## 怎么用
入口：左侧菜单「接口仿真 → 流量检视」。
1. 顶部选择项目，随即选择该项目下的 Mock 空间（空间在规则页创建并发布后才会出现在这里）。
2. 状态条绿=数据面正在按最新版规则对外服务；黄=有降级（新版本还没装载上、装载连续失败、或账本缓冲溢出），条上直接写明原因；红=此刻读不到数据面自检，这是如实上报，不等于规则丢了。
3. 「全部流量 / 只命中 / 只落空」三档筛选排掉噪音：排查「我的规则怎么没生效」直接切「只落空」。
4. 「实时刷新」勾选后每 2 秒拉一次新账本，取消勾选即停止轮询；离开页面自动停止。
5. 点任意一行打开右侧抽屉：请求快照（方法/路径/查询参数/请求头/请求体）+ 按规则声明序逐条判定的匹配轨迹，写明每条候选规则为什么被排除。

## 应答来源怎么标
每一条被应答的请求都留有来源记录，页面用徽标如实区分三种情况，绝不让你把「假装的答案」当成「真实集成」：
- 命中规则列显示规则名 = 这条应答来自你发布的 Mock 规则，属正常仿真。
- 紫色「AI 兜底应答」标 = 规则没有对上，系统按开关授权动用了一次大模型生成的答案。这是花了 token 的付费兜底，永远单独标注，不会伪装成规则命中。
- 灰色「真实服务转发」标 = 开着录制盒且绑定了真实目标时，请求被转发给了真实依赖，这条应答来自真实服务本身，仿真规则没有参与。
- 老记录或普通落空行没有来源标 = 该请求没有可归属的应答来源，页面不编造标签。

## 操作背后系统做了什么
- 装载状态条是现场读取数据面自检的结果，页面不缓存也不猜：读不到就明说读不到，绝不拿上一次的值冒充当前健康。
- 数据面装载新版本失败时，仍以上一次成功的版本继续对外服务（旧值不冒充新值，但也不至于停服），状态条把「连续失败几次、最近一次什么原因」原样呈现。
- 规则发布后数据面未及时装载上（状态条黄），期间进来的请求走的还是旧规则——匹配轨迹里能看到实际参与判定的候选集，不会用新规则解释旧行为。
- 账本写入走异步攒批：在途缓冲条数、是否已降级落盘、溢出丢弃条数都在状态条如实声明。丢弃只意味着账本有缺口，不意味着请求失败。
- 应答来源由数据面在给出答案的那一刻写下，随账本一起落库；页面只呈现落库的值，事后不改写、不补标。
- 请求快照里的敏感内容在进入页面之前就已由管道脱敏，检视器只渲染管道给出的值，页面上不存在第二次「解开看原文」的路径。
- 空间按路由优先级排序展示；一个空间对应一个数据面实例，切换空间即切换对应的装载自检与流量账本。

## 常见问题
- 选了项目却没有空间可选？——该项目还没建 Mock 空间，去接口仿真的规则页创建并发布一个。
- 状态条一直红？——数据面此刻不可达（进程没起来或地址配置指向了别处），先确认服务在线，页面不会假装健康。
- 流量列表是空的？——这个空间最近确实没有请求到达；检视器只呈现真实到过的流量，不生成示例数据。
- 明明配了规则却显示落空？——切「只落空」并展开该行匹配轨迹，逐条看候选规则被排除的原因（路径、方法、参数匹配条件与声明顺序都会影响结论）。
- 账本说丢弃了若干条，会影响判定吗？——丢弃的是账本记录，不是请求本身；要精确统计请先降低流量或调大缓冲。
- 看到「AI 兜底应答」标要不要担心？——它说明这一次请求没被规则覆盖而由大模型代答；若希望这类请求改为直接落空，可在系统配置里关闭该兜底开关，关闭后这类标不会再出现。
$mdq$,
    updated_at = now()
WHERE domain_code = 'T' AND title = '接口仿真：Mock 流量怎么看清命中与落空';

-- ################ V245__mock_ai_summarize_sample_cap.sql ################
-- AG batch (M10 : newest-frame cap for the A-4 induction sample.
--
-- Why this file exists:
--   The record-summarize leg (ai-service MockDraftGenServiceImpl) pulls a
--   bounded sample of a sealed box's masked frames before spending any token.
--   The cap must be an operator-visible, hot-tunable K8 row rather than a
--   code-only default: long cassettes (hundreds of frames) would otherwise
--   blow the prompt budget of the pinned 4000-token QUOTA stamped at create
--   time (V239/V241 posture). Core trims to the NEWEST N frames (capture
--   order tail) because recent traffic best represents the current contract;
--   reading stays honest either way — open box = live hold, sealed = cassette.
--   Values < 1 are clamped to 1 at read time (an empty sample would only
--   produce a failed job, so a nonsense key never silences induction).
--
-- Idempotent via ON CONFLICT DO NOTHING (re-run safe).
-- Usage: docker exec -i -e PGPASSWORD=... testpike-postgres psql -U ... -d testpike -f - < this file

INSERT INTO tp_sys_config (config_key, config_value, group_name, value_type, encrypt_flag, description)
VALUES
    ('mock.ai.summarize.max-sample-frames', '50', 'AI 配置', 'int', 0,
     'A-4 录制归纳单次采样的最新帧数上限：封盒流量再多也只取最新 N 帧进 prompt（帧均已脱敏）；热更即时生效，下一次归纳任务读取；<1 按 1 收拢，缺行按 50 回退')
ON CONFLICT (config_key) DO NOTHING;

-- ################ V246__mock_space_miss_policy.sql ################
-- AG batch : space-level miss policy — the three-rung ladder from
-- the design (passthrough | reject | llm-fallback) becomes a saved per-space
-- choice instead of being derived only from "is a recording box open".
--
-- Why this file exists:
--   1) Until now a miss escalated to the proxy rung ONLY while a cassette box
--      was open, and to the AI rung whenever the gates allowed. Operators had
--      no honest way to say "this space always rejects misses with 404+trace"
--      or "always try the bound target". The policy column is that declaration.
-- 2) Default 'llm-fallback' reproduces the derived ladder exactly
--      (recording-proxy rung → gated AI rung → 404), so every existing space
--      keeps its served semantics without a data migration beyond the default.
--
-- Usage: docker exec -i -e PGPASSWORD=... testpike-postgres psql -U ... -d testpike -f - < this file
ALTER TABLE tp_mock_space
    ADD COLUMN IF NOT EXISTS miss_policy VARCHAR(20) NOT NULL DEFAULT 'llm-fallback';

COMMENT ON COLUMN tp_mock_space.miss_policy IS
    'What a no-stub-match request does (passthrough: forward to the bound target; reject: honest 404+trace only; llm-fallback: recording-proxy rung then gated AI rung then 404 — the derived pre-policy ladder)';

-- Side-door guard mirrors the core validator spectrum (0-100 chaos posture).
ALTER TABLE tp_mock_space DROP CONSTRAINT IF EXISTS ck_mock_space_miss_policy;
ALTER TABLE tp_mock_space
    ADD CONSTRAINT ck_mock_space_miss_policy
    CHECK (miss_policy IN ('passthrough', 'reject', 'llm-fallback'));

-- ################ V247__automation_target_api.sql ################
-- Migration: widen the automation_target domain with 'api' .
-- Rationale: promoting a tuned sandbox request into a regression case creates a real
-- test case / suite asset whose automation target is api; it must flow through the
-- quality management chain (suite -> plan -> batch -> report -> exit gate). The domain
-- was web/app/mp/harmony, so an api target died at both the DB CHECK and the write-side
-- gate. Discipline (same as V219): tp_test_case AND tp_regression_suite widen together —
-- a half-widened domain (case accepts api, suite rejects it) breaks the asset chain.
-- Engine columns keep their existing constraints: NULL already means the runtime
-- "auto" default; the relaxation lives in the write-side gate, not the DB constraint.

ALTER TABLE tp_test_case DROP CONSTRAINT IF EXISTS ck_test_case_automation_target;
ALTER TABLE tp_test_case ADD CONSTRAINT ck_test_case_automation_target CHECK (
    automation_target IS NULL OR automation_target IN ('web', 'app', 'mp', 'harmony', 'api'));

ALTER TABLE tp_regression_suite DROP CONSTRAINT IF EXISTS ck_regression_suite_automation_target;
ALTER TABLE tp_regression_suite ADD CONSTRAINT ck_regression_suite_automation_target CHECK (
    automation_target IS NULL OR automation_target IN ('web', 'app', 'mp', 'harmony', 'api'));

COMMENT ON COLUMN tp_test_case.automation_target IS
    'automation target web/app/mp/harmony/api (NULL = unmounted, web semantics; harmony = HarmonyOS NEXT added in V219; api = interface regression case added in V247, runs inline http.request steps; end_type is an orthogonal business-end attribute)';
COMMENT ON COLUMN tp_regression_suite.automation_target IS
    'suite automation target web/app/mp/harmony/api (NULL = unmounted, web semantics; same domain as tp_test_case since V247)';

-- ################ V248__apitest_run_set.sql ################
-- Migration: collection-level run sets for the API test sandbox .
-- Why: running a whole collection needs a parent ledger above the per-request
-- tp_apitest_run rows. The set row carries the pinned definition snapshot
-- (definitions frozen at launch — design W-c2: the variable pool keeps evolving
-- during the run, definitions must not), the interruption mode (three fixed
-- spectra, never free expressions) and the aggregate traffic-light counts.
-- Child runs gain nullable run_set_id/seq_no: single-request runs keep the old
-- shape (both NULL) with zero drift.
-- Usage: docker exec -i -e PGPASSWORD=... testpike-postgres psql -U ... -d testpike -f - < this file

CREATE TABLE IF NOT EXISTS tp_apitest_run_set (
    id                 bigserial PRIMARY KEY,
    collection_id      bigint       NOT NULL REFERENCES tp_apitest_collection (id),
    project_id         bigint       NOT NULL,
    env_id             bigint,
    name               varchar(200) NOT NULL DEFAULT '',
    interruption_mode  varchar(32)  NOT NULL DEFAULT 'STOP_ON_ASSERT_FAIL',
    status             smallint     NOT NULL DEFAULT 0,
    pinned_json        jsonb        NOT NULL DEFAULT '[]'::jsonb,
    initial_vars_json  jsonb        NOT NULL DEFAULT '{}'::jsonb,
    total_steps        int          NOT NULL DEFAULT 0,
    passed_count       int          NOT NULL DEFAULT 0,
    failed_count       int          NOT NULL DEFAULT 0,
    skipped_count      int          NOT NULL DEFAULT 0,
    created_by         bigint,
    created_at         timestamp    NOT NULL DEFAULT now(),
    updated_at         timestamp    NOT NULL DEFAULT now(),
    CONSTRAINT ck_apitest_run_set_status
        CHECK (status IN (0, 1, 2, 3, 4)),
    CONSTRAINT ck_apitest_run_set_interruption
        CHECK (interruption_mode IN ('STOP_ON_ASSERT_FAIL', 'CONTINUE_AND_SUMMARY', 'CHAIN_DEP_ONLY'))
);

COMMENT ON TABLE tp_apitest_run_set IS
    'Whole-collection run ledger: definition snapshot pinned at launch, variable pool evolves; child rows live in tp_apitest_run via run_set_id/seq_no';
COMMENT ON COLUMN tp_apitest_run_set.status IS
    '0=queued 1=running 2=done-passed 3=done-with-failures 4=interrupted by the chosen mode';
COMMENT ON COLUMN tp_apitest_run_set.interruption_mode IS
    'STOP_ON_ASSERT_FAIL / CONTINUE_AND_SUMMARY / CHAIN_DEP_ONLY — form enums, no free expressions';
COMMENT ON COLUMN tp_apitest_run_set.pinned_json IS
    'Array of request definitions frozen at launch, tree order (ORDER BY id); source for the order-preview card and the CHAIN_DEP reference graph';
COMMENT ON COLUMN tp_apitest_run_set.initial_vars_json IS
    'Collection variable pool snapshot at launch (bookkeeping/display only — the live pool the executor seeds from is re-read per hop)';

CREATE INDEX IF NOT EXISTS idx_apitest_run_set_collection
    ON tp_apitest_run_set (collection_id);

ALTER TABLE tp_apitest_run
    ADD COLUMN IF NOT EXISTS run_set_id bigint REFERENCES tp_apitest_run_set (id);
ALTER TABLE tp_apitest_run
    ADD COLUMN IF NOT EXISTS seq_no int;

COMMENT ON COLUMN tp_apitest_run.run_set_id IS
    'Owning collection run (NULL = standalone single-request run, the pre-T369 shape)';
COMMENT ON COLUMN tp_apitest_run.seq_no IS
    '1-based position inside the pinned sequence (NULL for standalone runs)';

CREATE INDEX IF NOT EXISTS idx_apitest_run_run_set
    ON tp_apitest_run (run_set_id, seq_no);

-- ################ V249__apitest_run_dispatch_stamp.sql ################
-- Migration: dispatch stamp + skipped terminal for collection-run orchestration .
-- Why: the orchestrator sends one hop at a time and must never double-dispatch
-- when two result callbacks race inside one set. A NULL dispatch stamp is the
-- durable "never sent" marker — the row-level guard paired with the set-row
-- FOR UPDATE lock (docs/10 concurrency protection, same posture).
-- Child status gains 4 = suppressed skip (interrupted chain hop: terminal
-- without an envelope, honest traffic-light accounting).
-- Usage: docker exec -i -e PGPASSWORD=... testpike-postgres psql -U ... -d testpike -f - < this file

ALTER TABLE tp_apitest_run
    ADD COLUMN IF NOT EXISTS dispatched_at timestamp;

COMMENT ON COLUMN tp_apitest_run.dispatched_at IS
    'When the executor envelope for this run was created (NULL = never dispatched; the advance guard never re-sends a stamped row)';
COMMENT ON COLUMN tp_apitest_run.status IS
    '0=pending 1=passed 2=assertion failed 3=execution error 4=skipped by the collection interruption mode';

CREATE INDEX IF NOT EXISTS idx_apitest_run_set_pending
    ON tp_apitest_run (run_set_id, seq_no)
    WHERE run_set_id IS NOT NULL AND dispatched_at IS NULL;

-- ################ V250__apitest_contract_endpoint_key.sql ################
-- First-class match key on the API request table (AH batch W1c, stage 1).
-- Rationale: contract badge / inventory joins / change-impact closure all need to
-- resolve "which requests sit on this endpoint" by equality on a stored key.
-- Before this migration the key was recomputed per row at query time — fine for a
-- badge, but a full-table re-scan per endpoint once the inventory page lists N
-- endpoints, and the raw-string match was blind to hand-written concrete paths
-- (GET /orders/20261011001 never equals the contract template GET /orders/{id}).
-- Semantics (single source = ContractMatchKeyRules, this SQL mirrors it for the
-- one-time backfill only; the write path always recomputes via the Java rules):
--   key = upper(method) + ' ' + path, with variable-shaped segments folded to
--   {var}: template {x}, pure numeric, UUID, long hex (>=16); query string and
--   trailing slash stripped as in OpenApiSpecParser.normalizePath.
-- New K8 key spec.path-normalize.rules: CSV of extra segment regexes folded to
-- {var} (hot-update, built-in conservative rules need no config).
-- Manual execution (Flyway not enabled):
--   docker exec -i testpike-postgres psql -U testpike -d testpike < db/migration/V250__apitest_contract_endpoint_key.sql
-- After landing the new key, rebuild the config snapshot (pit 21 defence):
--   python3 scripts/tmp_m8p4_build_snapshot.py

ALTER TABLE tp_apitest_request
    ADD COLUMN IF NOT EXISTS contract_endpoint_key VARCHAR(1100) NULL;

COMMENT ON COLUMN tp_apitest_request.contract_endpoint_key IS
    'Normalized contract match key (upper METHOD + path with numeric/UUID/long-hex/template segments folded to {var}); written by the save chain, indexed for inventory joins and change-impact closure';

UPDATE tp_apitest_request
   SET contract_endpoint_key = upper(trim(method)) || ' ' ||
       regexp_replace(
           regexp_replace(
               regexp_replace(
                   regexp_replace(
                       regexp_replace(
                           CASE WHEN split_part(url_path, '?', 1) = '' THEN '/'
                                WHEN split_part(url_path, '?', 1) LIKE '/%'
                                     THEN split_part(url_path, '?', 1)
                                ELSE '/' || split_part(url_path, '?', 1) END,
                           '/{2,}', '/'),
                       '\{[^}]*\}', '{var}', 'g'),
                   '/[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}(?=/|$)', '/{var}', 'g'),
               '/[0-9]+(?=/|$)', '/{var}', 'g'),
           '/[0-9a-fA-F]{16,}(?=/|$)', '/{var}', 'g')
 WHERE contract_endpoint_key IS NULL;

CREATE INDEX IF NOT EXISTS ix_apitest_request_contract_key
    ON tp_apitest_request (contract_endpoint_key);

