-- ################ V270__exec_task_reclaim_trace.sql ################
-- V270: reclaim trace columns on tp_exec_task (crash-recovery reconciliation)
-- Why: the 15s offline-sweep job and the manual batch recover action reclaim the same
-- "running task on an offline executor" rows; whoever wins first drains the other's
-- candidate set, so a manual recover could report "nothing to reclaim" with no way to
-- explain where reclaimed tasks went. Recording which path reclaimed a task lets the
-- recover view state, in plain words, how many tasks were already reclaimed by the
-- automatic sweep and are still queued.
-- last_reclaim_source: 1 = automatic offline-sweep job, 2 = manual batch recovery.
-- NULL = never reclaimed (task never dangled, or legacy rows before this migration).
ALTER TABLE tp_exec_task ADD COLUMN IF NOT EXISTS last_reclaim_source SMALLINT;
ALTER TABLE tp_exec_task ADD COLUMN IF NOT EXISTS last_reclaimed_at TIMESTAMPTZ;

COMMENT ON COLUMN tp_exec_task.last_reclaim_source IS
    'Which reclaim path last moved this task back to the pending queue: 1=automatic offline sweep, 2=manual batch recovery; NULL=never reclaimed';
COMMENT ON COLUMN tp_exec_task.last_reclaimed_at IS
    'Timestamp of the last reclaim move (matching last_reclaim_source); NULL=never reclaimed';

-- ################ V271__perf_scenario_isolation_mode.sql ################
-- Perf scenario isolation-mode column: production-bound scenarios must carry a declared
-- isolation mode (shadow table / namespace account / header mark). Before this migration the
-- declaration only lived in the wizard's precheck call and was never persisted, so a launch
-- that skipped the wizard carried no isolation truth into the gate or the pressure snapshot.
ALTER TABLE tp_perf_scenario ADD COLUMN IF NOT EXISTS isolation_mode VARCHAR(20);

ALTER TABLE tp_perf_scenario DROP CONSTRAINT IF EXISTS ck_perf_scenario_isolation_mode;
ALTER TABLE tp_perf_scenario ADD CONSTRAINT ck_perf_scenario_isolation_mode
    CHECK (isolation_mode IS NULL OR isolation_mode IN ('SHADOW_TABLE', 'NS_ACCOUNT', 'HEADER_MARK'));

COMMENT ON COLUMN tp_perf_scenario.isolation_mode IS 'Declared isolation mode (SHADOW_TABLE/NS_ACCOUNT/HEADER_MARK); NULL = not declared, only legal for non-production scenarios; the production launch gate rejects a missing declaration';

-- ################ V272__perf_budget_margin_key.sql ################
-- Migration: A-14 perf run budget margin key seed (K8 hot-updatable, default 10 minutes).
-- Semantics: the dispatch-envelope budget = scenario run duration + this margin; claim hands
--   it to the executor as timeoutMs for task_type=5, and the timeout sweep judges perf rows
--   by it. 0 = no margin (raw duration); negative / non-numeric / missing falls back to 10
--   in PerfConfigReader.budgetMarginMinutes (single point).
-- Idempotent re-run: ON CONFLICT (config_key) DO NOTHING.
-- Usage: docker cp db/migration/V272__perf_budget_margin_key.sql testpike-postgres:/tmp/ && docker exec -e PGPASSWORD testpike-postgres psql -U testpike -d testpike -f /tmp/V272__perf_budget_margin_key.sql
INSERT INTO tp_sys_config (config_key, config_value, group_name, value_type, encrypt_flag, description)
VALUES
    ('perf.budget-margin-minutes', '10', '系统', 'int', 0,
     '压测预算宽限分钟（长跑预算=场景时长+本宽限；0=不加宽限，非法回退 10，热更即生效）')
ON CONFLICT (config_key) DO NOTHING;

-- ################ V273__perf_dataset_ledger.sql ################
-- Migration: perf CSV dataset ledger (data pool on MinIO with column preview and K8 row budget).
-- Semantics: one row = one uploaded CSV file of a project. The bytes live in object storage
--   (scene perf-dataset, project-routed like explore evidence); this table keeps only metadata:
--   validated header column names (columns_json, reused as {{VAR}} names in scenario steps),
--   the validated data-row count and the object key. Preview is streamed back from the object,
--   never from a duplicated DB copy of the payload.
-- K8 keys: perf.dataset.max-rows = upload row budget; perf.dataset.preview-rows = preview window.
--   Both hot-updatable; invalid/missing falls back to defaults in PerfConfigReader (single point).
-- Idempotent re-run: CREATE TABLE IF NOT EXISTS + ON CONFLICT DO NOTHING.
-- Usage: docker cp db/migration/V273__perf_dataset_ledger.sql testpike-postgres:/tmp/ && docker exec -e PGPASSWORD testpike-postgres psql -U testpike -d testpike -f /tmp/V273__perf_dataset_ledger.sql
CREATE TABLE IF NOT EXISTS tp_perf_dataset (
    id            BIGSERIAL    PRIMARY KEY,
    project_id    BIGINT       NOT NULL REFERENCES tp_project (id),
    name          VARCHAR(200) NOT NULL,
    file_name     VARCHAR(300) NOT NULL,
    object_key    VARCHAR(600) NOT NULL,
    columns_json  JSONB        NOT NULL,
    row_count     INT          NOT NULL,
    size_bytes    BIGINT       NOT NULL,
    created_at    TIMESTAMP    NOT NULL DEFAULT now(),
    updated_at    TIMESTAMP    NOT NULL DEFAULT now(),
    CONSTRAINT ck_perf_dataset_row_count CHECK (row_count >= 1),
    CONSTRAINT uq_perf_dataset_name UNIQUE (project_id, name)
);

CREATE INDEX IF NOT EXISTS ix_perf_dataset_project ON tp_perf_dataset (project_id, id DESC);

COMMENT ON TABLE tp_perf_dataset IS 'Perf CSV dataset ledger: file bytes live in object storage (scene perf-dataset); this table keeps metadata only (validated columns, row count, object key)';
COMMENT ON COLUMN tp_perf_dataset.columns_json IS 'Validated CSV header names stored at upload; the same names form the {{VAR}} variable domain usable by scenario steps';
COMMENT ON COLUMN tp_perf_dataset.object_key IS 'Canonical object key (StorageKeys scene perf-dataset, project-routed; read and write resolve to the same provider)';

INSERT INTO tp_sys_config (config_key, config_value, group_name, value_type, encrypt_flag, description)
VALUES
    ('perf.dataset.max-rows', '50000', '系统', 'int', 0,
     '压测数据集 CSV 行数上限（上传时按数据行计数校验，超限拒绝并提示当前上限；非法值回退 50000，热更即生效）'),
    ('perf.dataset.preview-rows', '20', '系统', 'int', 0,
     '压测数据集预览行数（查看数据集时回显的前 N 行数据；非法值回退 20，热更即生效）')
ON CONFLICT (config_key) DO NOTHING;

-- ################ V274__perf_scenario_dataset_binding.sql ################
-- Migration: bind a perf scenario to a CSV dataset (data pool) with a row-allocation strategy.
-- Semantics: tp_perf_scenario.dataset_id = the uploaded CSV ledger row whose header column names
--   form the {{VAR}} domain consumed by steps; NULL = scenario runs without a data pool (today's
--   behaviour, zero regression). row_alloc_mode stores the scenario-level choice over the three
--   allocation strategies; NULL = resolve the K8 default key at dispatch time (hot-updatable,
--   never hardcoded at call sites).
-- Allocation strategies (value domain enforced at save, single source ROW_ALLOC_MODES in core):
--   SEQUENTIAL_EXCLUSIVE = each row is handed out once in file order (rows are consumed, never
--     duplicated while the run still has unleased rows);
-- VUSER_EXCLUSIVE = every virtual user owns a private segment and never shares a row;
--   CYCLE                = rows are reused round-robin after the pool is exhausted (safe default:
--     a run can never stall on "no row left", dirty data may be re-submitted).
-- K8 key: perf.dataset.row-alloc-mode = pool-wide default when the scenario leaves the column NULL;
--   hot-updatable; invalid/missing falls back to CYCLE in PerfConfigReader (single point).
-- FK note: tp_perf_dataset row cannot be deleted while a scenario still references it — the
--   dataset delete service pre-checks references and refuses with a plain-worded reason.
-- Idempotent re-run: ADD COLUMN IF NOT EXISTS + ON CONFLICT DO NOTHING.
-- Usage: docker cp db/migration/V274__perf_scenario_dataset_binding.sql testpike-postgres:/tmp/ && docker exec -e PGPASSWORD testpike-postgres psql -U testpike -d testpike -f /tmp/V274__perf_scenario_dataset_binding.sql
ALTER TABLE tp_perf_scenario ADD COLUMN IF NOT EXISTS dataset_id BIGINT REFERENCES tp_perf_dataset (id);
ALTER TABLE tp_perf_scenario ADD COLUMN IF NOT EXISTS row_alloc_mode VARCHAR(24);

COMMENT ON COLUMN tp_perf_scenario.dataset_id IS 'Bound CSV dataset (tp_perf_dataset.id); NULL = no data pool, steps resolve {{VAR}} only from non-dataset sources';
COMMENT ON COLUMN tp_perf_scenario.row_alloc_mode IS 'Row allocation strategy SEQUENTIAL_EXCLUSIVE/VUSER_EXCLUSIVE/CYCLE; NULL = follow K8 default key perf.dataset.row-alloc-mode at dispatch';

CREATE INDEX IF NOT EXISTS ix_perf_scenario_dataset ON tp_perf_scenario (dataset_id);

INSERT INTO tp_sys_config (config_key, config_value, group_name, value_type, encrypt_flag, description)
VALUES
    ('perf.dataset.row-alloc-mode', 'CYCLE', '系统', 'string', 0,
     '压测数据集行分配默认策略（场景未显式声明时生效：SEQUENTIAL_EXCLUSIVE 独占顺序/VUSER_EXCLUSIVE 每虚拟用户独占/CYCLE 循环复用；非法值回退 CYCLE，热更即生效）')
ON CONFLICT (config_key) DO NOTHING;

-- ################ V275__perf_metric_bucket_step.sql ################
-- Migration: A-7/B-4/B-6 — tp_perf_metric gains request-count buckets, a latency histogram,
--   an error-class breakdown and a step dimension, so full-run percentile and weighted error-rate
--   recomputation have raw material (per-second p95-max / equal-weight mean are mathematically
--   unsound as whole-run calibers).
-- Semantics:
--   req_count / fail_count = completed / failed requests of that second (and step); NULL = legacy
--     frame from an executor that predates bucket reporting — the judge then falls back to the
--     per-second caliber (single judgment family, degradation noted in the conclusion line).
--   duration_sum_ms = sum of response times that second; whole-run mean = SUM(duration_sum)/SUM(req).
--   hist = JSONB integer array of histogram bucket counts; bucket boundaries are a fixed contract
--     shared with core PerfHistogram (rank-based full-run percentiles merge these arrays).
--   error_class = JSONB object {timeout, refused, http4xx, http5xx, biz} counts for the TopN
--     error-class drawer; NULL = not collected.
--   step_key = '' (empty string, never NULL) for un-split frames, so existing rows stay valid
--     under the new uniqueness anchor (D3 ruling: column form, key migrated below).
-- Uniqueness: uq_perf_metric_frame moves from (run_id, second_offset) to
--   (run_id, second_offset, step_key) — replay idempotency anchor per step; legacy rows backfill
--   step_key='' so the index build cannot fail on duplicates.
-- K8 seeds (hot-updatable thresholds, never hardcoded at call sites):
--   perf.frames-flush-interval-seconds = how often the worker ships partial frames with heartbeats;
--   perf.max-duration-hours = launch-time guard rejecting runs longer than the soak batch limit.
-- Idempotent re-run: ADD COLUMN IF NOT EXISTS + guarded index drop/create + ON CONFLICT DO NOTHING.
-- Usage: docker cp db/migration/V275__perf_metric_bucket_step.sql testpike-postgres:/tmp/ && docker exec -e PGPASSWORD testpike-postgres psql -U testpike -d testpike -f /tmp/V275__perf_metric_bucket_step.sql
ALTER TABLE tp_perf_metric ADD COLUMN IF NOT EXISTS req_count       BIGINT;
ALTER TABLE tp_perf_metric ADD COLUMN IF NOT EXISTS fail_count      BIGINT;
ALTER TABLE tp_perf_metric ADD COLUMN IF NOT EXISTS duration_sum_ms NUMERIC(14,2);
ALTER TABLE tp_perf_metric ADD COLUMN IF NOT EXISTS hist            JSONB;
ALTER TABLE tp_perf_metric ADD COLUMN IF NOT EXISTS error_class     JSONB;
ALTER TABLE tp_perf_metric ADD COLUMN IF NOT EXISTS step_key        VARCHAR(64) NOT NULL DEFAULT '';

-- Value-domain guards (NULL-tolerant: legacy frames stay legal; bucket frames must satisfy
-- fail<=req and non-negative sums — the ingestion face rejects with a row-numbered message first).
ALTER TABLE tp_perf_metric DROP CONSTRAINT IF EXISTS ck_perf_metric_bucket_counts;
ALTER TABLE tp_perf_metric ADD CONSTRAINT ck_perf_metric_bucket_counts
    CHECK (fail_count IS NULL OR req_count IS NULL OR (fail_count >= 0 AND fail_count <= req_count));
ALTER TABLE tp_perf_metric DROP CONSTRAINT IF EXISTS ck_perf_metric_duration_sum;
ALTER TABLE tp_perf_metric ADD CONSTRAINT ck_perf_metric_duration_sum
    CHECK (duration_sum_ms IS NULL OR duration_sum_ms >= 0);

-- Uniqueness anchor migration: (run_id, second_offset) -> (run_id, second_offset, step_key).
UPDATE tp_perf_metric SET step_key = '' WHERE step_key IS NULL;
ALTER TABLE tp_perf_metric DROP CONSTRAINT IF EXISTS uq_perf_metric_frame;
CREATE UNIQUE INDEX IF NOT EXISTS uq_perf_metric_frame
    ON tp_perf_metric (run_id, second_offset, step_key);

COMMENT ON COLUMN tp_perf_metric.req_count IS 'Completed requests of this second and step; raw material for weighted error rate and full-run percentile recomputation. NULL = legacy frame without buckets, judge falls back to the per-second caliber';
COMMENT ON COLUMN tp_perf_metric.fail_count IS 'Failed requests of this second and step; always <= req_count, enforced by ck_perf_metric_bucket_counts';
COMMENT ON COLUMN tp_perf_metric.duration_sum_ms IS 'Sum of response times this second and step (ms); whole-run mean = SUM(duration_sum)/SUM(req)';
COMMENT ON COLUMN tp_perf_metric.hist IS 'Latency histogram bucket counts (JSONB integer array; bucket boundaries shared with core PerfHistogram; over-cap values land in the last bucket)';
COMMENT ON COLUMN tp_perf_metric.error_class IS 'Error-class counts (JSONB {timeout,refused,http4xx,http5xx,biz}); data source of the TopN error drawer, NULL = not collected';
COMMENT ON COLUMN tp_perf_metric.step_key IS 'Step key; empty string = un-split frame (legacy shape). Third column of the idempotency anchor so same-second frames of different steps stay distinct';

-- K8 key seeds (defaults mirror PerfConfigReader.DEFAULTS; hot-updatable).
INSERT INTO tp_sys_config (config_key, config_value, group_name, value_type, encrypt_flag, description)
VALUES
    ('perf.frames-flush-interval-seconds', '10', '系统', 'int', 0,
     '压测部分帧随心跳回传的最小间隔秒（执行器侧攒帧窗口；过小=派发通道噪音，过大=实况曲线迟滞）'),
    ('perf.max-duration-hours', '4', '系统', 'int', 0,
     '压测单次 run 最长时长小时闸（发起时拒单上限；长跑拆批的前提护栏，默认 4 小时= soak 分批口径）')
ON CONFLICT (config_key) DO NOTHING;

-- ################ V276__perf_live_curve_max_points.sql ################
-- Migration: GA-3 — K8 seed for the live-curve point ceiling.
-- The running page polls the curve every 2s; without an incremental cursor + server-side
-- downsampling a 4h soak re-ships up to 14400 raw seconds per poll. The ceiling below is
-- the max points one live-curve response may carry — above it the server collapses seconds
-- into buckets (p95 = bucket max, error rate = request-weighted) and honestly annotates
-- sampled=true. Report pages keep reading the full unsampled series.
-- Values: <10 or >10000 or non-numeric falls back to 600 in PerfConfigReader (a dirty
-- value can never flood the poll nor starve the curve below one screen).
-- Idempotent: ON CONFLICT DO NOTHING.
