-- assembly, the prompt keeps only ai.tool.catalog-core-tools resident plus the
-- built-in search_tools meta-tool; the rest ride a compact catalog line and are
-- materialized on demand (max ai.tool.catalog-expand-max per search).
-- Routing/authorization is unaffected: every candidate stays dispatch-eligible.
-- Applied manually to the dev DB (Flyway is not enabled; db/migration is
-- reference), then db/schema-init.sql regenerated via tools/ops/gen_schema_init.sh.
INSERT INTO tp_sys_config (config_key, config_value, group_name, value_type, encrypt_flag, description) VALUES
    ('ai.tool.catalog-threshold', '20', '系统', 'int', 0, '工具目录延迟装配的触发件数（默认 20；项目可用工具数超过它时，非核心工具不再逐条占用请求清单，改为按需检索；填 0 或负数=关闭该机制，全部工具常驻下发，修改即时生效）'),
    ('ai.tool.catalog-core-tools', '', '系统', 'string', 0, '始终常驻下发的核心工具名单（英文逗号分隔的工具名，默认为空=无核心常驻；名单内的工具即使触发目录延迟装配也会直接随请求提供，无需先检索）'),
    ('ai.tool.catalog-expand-max', '8', '系统', 'int', 0, '每次检索目录最多展开的工具数（默认 8；一次检索命中的工具超过上限时按目录顺序取前 8 个随下一轮请求下发，其余可再次检索获取，修改即时生效）')
ON CONFLICT (config_key) DO NOTHING;

-- ################ V353__ai_ctx_memory_table.sql ################
-- Migration: project memory entry table for the AP batch .
-- Semantic: distilled project-convention entries injected into the assembly
-- context (caps ai.ctx.memory-max-items, relevance-trimmed). The pin-facts
-- layer itself lives in tp_ai_chat_session.context_json and is independent of
-- this lossy-trimmed layer; distillation writes and the /skills ledger view
-- land with / and consume this table.
CREATE TABLE IF NOT EXISTS tp_ai_ctx_memory (
    id            BIGSERIAL PRIMARY KEY,
    project_id    BIGINT      NOT NULL,
    content       TEXT        NOT NULL,
    source_ref    JSONB       NOT NULL,
    inject_status SMALLINT    NOT NULL DEFAULT 1,
    hit_count     BIGINT      NOT NULL DEFAULT 0,
    created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at    TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_ai_ctx_memory_project ON tp_ai_ctx_memory (project_id, inject_status);

COMMENT ON TABLE tp_ai_ctx_memory IS
    'Project memory entries distilled from review rejections, healing diffs, dialog downvotes and refusals (AP batch; injection cap via ai.ctx.memory-max-items)';
COMMENT ON COLUMN tp_ai_ctx_memory.project_id IS 'Owning project (tp_project.id); entries never cross projects';
COMMENT ON COLUMN tp_ai_ctx_memory.content IS 'The distilled project convention text injected into assembly';
COMMENT ON COLUMN tp_ai_ctx_memory.source_ref IS 'Traceability anchors [{type,id}] naming the rejection/downvote/healing-diff sources (T449 ledger view)';
COMMENT ON COLUMN tp_ai_ctx_memory.inject_status IS '1 = eligible for assembly injection, 0 = operator-disabled through the ledger view (governed by T449)';
COMMENT ON COLUMN tp_ai_ctx_memory.hit_count IS 'Times this entry took part in assembly, read-only accounting for the ledger view';

-- ################ V354__perf_scenario_engine_jmeter.sql ################
-- W-d third engine (JMeter): widen the scenario engine CHECK to accept JMETER.
-- Same posture as V289 (drop + re-add, NULL stays allowed = engine optional per scenario).
ALTER TABLE tp_perf_scenario DROP CONSTRAINT IF EXISTS ck_perf_scenario_engine;
ALTER TABLE tp_perf_scenario ADD CONSTRAINT ck_perf_scenario_engine
    CHECK (engine IS NULL OR engine IN ('K6', 'GATLING', 'JMETER'));

-- ################ V355__llm_cache_hint_and_cached_tokens.sql ################
-- AP-4 (prefix stabilization): per-model cache hint switch and the
-- provider-reported cached prompt tokens carried on every usage sample.
-- tp_llm_config.cache_hint: 1 = the caller may attach provider prompt-cache
-- hints on multi-turn requests (factory default ON per the AI-feature rule:
-- ships enabled, zero configuration; a provider that does not support cache
-- hints simply ignores them, so there is no failure mode to guard). 0 = never
-- send hints for this model (opt-out row, auditable).
-- tp_llm_usage_sample.cached_tokens: number of prompt tokens the provider
-- served from its prefix cache for this call (usage.prompt_tokens_details
-- .cached_tokens; absent block reads an honest 0). The E9 usage calibration
-- page shows the before/after difference of this column, so the AP-6 benefit
-- is measured from real traffic instead of promised upfront.
ALTER TABLE tp_llm_config ADD COLUMN IF NOT EXISTS cache_hint SMALLINT NOT NULL DEFAULT 1;
COMMENT ON COLUMN tp_llm_config.cache_hint IS
    'Prompt-cache hint switch for this model (1 = allowed, factory default; 0 = opt out). Controls request-side cache hints only; never bypasses the write-confirmation gate.';

ALTER TABLE tp_llm_usage_sample ADD COLUMN IF NOT EXISTS cached_tokens INTEGER NOT NULL DEFAULT 0;
COMMENT ON COLUMN tp_llm_usage_sample.cached_tokens IS
    'Prompt tokens served from the provider prefix cache for this call (usage.prompt_tokens_details.cached_tokens; 0 = none reported).';

-- ################ V357__spec_subscription_program_source.sql ################
-- Migration V357: contract subscription gains the set-internal reference source .
-- A tp_spec_subscription row now carries source_kind: 'url' = external http(s) pull
-- (V131 original semantics) or 'program_spec' = consumer project subscribes the LATEST
-- version of a provider project's spec inside a shared program (project set lens, V340).
-- url becomes nullable; provider pair columns populate only program_spec rows; CHECK
-- constraints keep the url/pair invariant in the schema itself.
-- Flyway not enabled: apply manually to dev db.
-- Usage: docker exec -i testpike-postgres psql -U testpike -d testpike < db/migration/V357__spec_subscription_program_source.sql

ALTER TABLE tp_spec_subscription ALTER COLUMN url DROP NOT NULL;
ALTER TABLE tp_spec_subscription ADD COLUMN IF NOT EXISTS source_kind VARCHAR(16) NOT NULL DEFAULT 'url';
ALTER TABLE tp_spec_subscription ADD COLUMN IF NOT EXISTS provider_project_id BIGINT;
ALTER TABLE tp_spec_subscription ADD COLUMN IF NOT EXISTS provider_spec_name VARCHAR(200);

ALTER TABLE tp_spec_subscription DROP CONSTRAINT IF EXISTS ck_spec_subscription_source_kind;
ALTER TABLE tp_spec_subscription ADD CONSTRAINT ck_spec_subscription_source_kind
    CHECK (source_kind IN ('url', 'program_spec'));
ALTER TABLE tp_spec_subscription DROP CONSTRAINT IF EXISTS ck_spec_subscription_source_fields;
ALTER TABLE tp_spec_subscription ADD CONSTRAINT ck_spec_subscription_source_fields
    CHECK ((source_kind = 'url' AND url IS NOT NULL)
        OR (source_kind = 'program_spec' AND provider_project_id IS NOT NULL
            AND provider_spec_name IS NOT NULL));

COMMENT ON COLUMN tp_spec_subscription.source_kind IS 'Pull source: url = external http(s) fetch (V131), program_spec = in-program provider contract reference (T287)';
COMMENT ON COLUMN tp_spec_subscription.provider_project_id IS 'Provider project id for program_spec rows; set-membership fence validated in the service single source';
COMMENT ON COLUMN tp_spec_subscription.provider_spec_name IS 'Provider contract name whose latest version row is the pull target';

-- The change-analysis ledger records which entry point landed a version (V253
-- detected_source). The set-internal subscription pull is a new entry point tag
-- 'program', so the allowed set widens to upload|fetch|poll|program.
ALTER TABLE tp_api_spec_change_analysis DROP CONSTRAINT IF EXISTS ck_spec_change_analysis_source;
ALTER TABLE tp_api_spec_change_analysis ADD CONSTRAINT ck_spec_change_analysis_source
    CHECK (detected_source IN ('upload', 'fetch', 'poll', 'program'));
COMMENT ON COLUMN tp_api_spec_change_analysis.detected_source IS 'upload | fetch | poll | program (which entry point landed this version; program = set-internal subscription pull, T287)';

-- ################ V358__shared_asset_publish_chain.sql ################
-- Migration V358: shared asset publish chain .
-- tp_asset is a single-table version chain modelled after tp_api_spec (V109) — reusing
-- the established chain shape instead of a second version mechanism. Publishing the
-- same (project_id, kind, name) again appends a row with asset_version+1 and links
-- prev_asset_id to the previous row. Owner = publishing project (project_id NOT NULL);
-- published heads are globally discoverable, every write (re-publish / withdraw) is
-- fenced to the owner project server-side (SharedAssetVisibilityGuard single source).
-- status: 1 = published, 2 = withdrawn at chain level; superseded version rows stay
-- readable because references pin concrete row ids (tp_asset_reference, .
-- payload_json is a content snapshot of the publisher's entity, never a live pointer;
-- credential material is stored as {{CRED:key}} names only (V257 discipline).
-- Flyway not enabled: apply manually to dev db.
-- Usage: docker exec -i testpike-postgres psql -U testpike -d testpike < db/migration/V358__shared_asset_publish_chain.sql

CREATE TABLE IF NOT EXISTS tp_asset (
    id            BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    project_id    BIGINT        NOT NULL,
    kind          VARCHAR(24)   NOT NULL,
    name          VARCHAR(200)  NOT NULL,
    asset_version INT           NOT NULL DEFAULT 1,
    prev_asset_id BIGINT,
    status        SMALLINT      NOT NULL DEFAULT 1,
    payload_json  TEXT          NOT NULL,
    created_by    BIGINT,
    created_at    TIMESTAMPTZ   NOT NULL DEFAULT now(),
    updated_at    TIMESTAMPTZ   NOT NULL DEFAULT now(),
    CONSTRAINT ck_asset_kind CHECK (kind IN
        ('case_fragment', 'action_component', 'login_recipe', 'gen_function')),
    CONSTRAINT ck_asset_status CHECK (status IN (1, 2)),
    CONSTRAINT uq_asset_project_kind_name_version UNIQUE (project_id, kind, name, asset_version)
);
CREATE INDEX IF NOT EXISTS idx_asset_chain_head
    ON tp_asset (project_id, kind, name, asset_version DESC);

COMMENT ON TABLE  tp_asset               IS 'Shared asset publish chain: per-project version-linked content snapshots (T288 slice 1)';
COMMENT ON COLUMN tp_asset.project_id    IS 'Owner = publishing project; cross-project readers gain discoverability only, never write access';
COMMENT ON COLUMN tp_asset.kind          IS 'Asset kind: case_fragment | action_component | login_recipe | gen_function';
COMMENT ON COLUMN tp_asset.prev_asset_id IS 'Previous version row id (chain link); NULL for the first publish';
COMMENT ON COLUMN tp_asset.status        IS '1 = published (head globally discoverable), 2 = withdrawn at chain level';
COMMENT ON COLUMN tp_asset.payload_json  IS 'Per-kind content snapshot (case step array / action JSON fragment / login recipe template / data factory content); credential values stay out, only {{CRED:key}} names';

-- ################ V359__shared_asset_reference_pin.sql ################
-- Migration V359: shared asset reference pins .
-- tp_asset_reference pins one host entity (referrer_kind + referrer_id) to exactly one
-- concrete tp_asset version row. Re-publishing upstream never moves the pin: consumers
-- see the staleness marker and explicitly re-pin (upsert keeps a single row per host),
-- so both directions of the bidirectional query stay single-SQL and N+1-free:
--   "who uses me"  = rows joined on the asset chain (project_id, kind, name)
--   "what I use"   = rows filtered by referrer_project_id
-- referrer_id is a logical locator resolved by the consuming domain (case step, journey
-- step, plan host, ...); no FK is declared because the host table varies by kind.
-- Pinned version rows must stay readable after chain withdrawal, hence no cascade rules.
-- Flyway not enabled: apply manually to dev db.
-- Usage: docker exec -i testpike-postgres psql -U testpike -d testpike < db/migration/V359__shared_asset_reference_pin.sql

CREATE TABLE IF NOT EXISTS tp_asset_reference (
    id                  BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    asset_row_id        BIGINT   NOT NULL REFERENCES tp_asset (id),
    referrer_project_id BIGINT   NOT NULL REFERENCES tp_project (id),
    referrer_kind       VARCHAR(32) NOT NULL,
    referrer_id         BIGINT   NOT NULL,
    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT uq_asset_reference_host UNIQUE (referrer_kind, referrer_id)
);
CREATE INDEX IF NOT EXISTS idx_asset_reference_row
    ON tp_asset_reference (asset_row_id);
CREATE INDEX IF NOT EXISTS idx_asset_reference_project
    ON tp_asset_reference (referrer_project_id);

COMMENT ON TABLE  tp_asset_reference                   IS 'Shared asset pool reference pins: host entity -> concrete tp_asset version row (T288 slice 2)';
COMMENT ON COLUMN tp_asset_reference.asset_row_id      IS 'Pinned tp_asset version row id; never auto-follows a re-publish (staleness is surfaced, re-pin is explicit)';
COMMENT ON COLUMN tp_asset_reference.referrer_project_id IS 'Consumer project that owns the host entity; write calls are fenced to the acting project server-side';
COMMENT ON COLUMN tp_asset_reference.referrer_kind     IS 'Host entity type literal (e.g. case_step); resolved by the consuming domain, no cross-table FK';
COMMENT ON COLUMN tp_asset_reference.referrer_id       IS 'Host entity row id inside the consumer project; unique per (referrer_kind, referrer_id) so a host holds exactly one pin';

-- ################ V360__ai_dedup_gate_keys.sql ################
-- Migration: seed the duplicate-gate key group (ai.dedup.*) for requirement writes.
--
-- Why this file exists:
--   Every create-type draft must pass the three-tier duplicate gate before a
--   new row lands, and the operator must be able to retune the gate without a
--   redeploy: the master switch, the two similarity lines that split the high
--   (refuse) / medium (present candidates) / low (pass) bands, and how many
--   near neighbours a medium verdict shows. Readers parse these strings and
--   clamp them (DedupGate), falling back to these seeded defaults on missing
--   or garbage values; the switch ships on (out-of-the-box duplicate
--   protection, no configuration required).
-- Applied manually to the dev DB (Flyway is not enabled; db/migration is
-- reference), then db/schema-init.sql regenerated via tools/ops/gen_schema_init.sh.
INSERT INTO tp_sys_config (config_key, config_value, group_name, value_type, encrypt_flag, description) VALUES
    ('ai.dedup.enabled', '1', '系统', 'string', 0, '新建需求重复检出开关（默认开启；在本页修改即时生效；关闭后新建不再做重复检出，直接按原流程创建）'),
    ('ai.dedup.l2-high-score', '0.85', '系统', 'string', 0, '疑似重复高相似界线（0.05~1；在本页修改即时生效；标题相似度达到该值按重复拦截并点名既有条目）'),
    ('ai.dedup.l2-mid-score', '0.60', '系统', 'string', 0, '疑似重复中相似界线（0.05~高界线之间；相似度达到该值出相近条目清单供确认；低于该值直接放行）'),
    ('ai.dedup.candidate-top-n', '5', '系统', 'int', 0, '疑似重复相近条目展示条数（默认 5；区间 1~20，在本页修改即时生效）')
ON CONFLICT (config_key) DO NOTHING;

-- ################ V361__ai_ctx_memory_deleted_flag.sql ################
-- Migration: soft-delete flag for the project-memory ledger .
-- Semantic: the ledger page governed by exposes disable/enable + delete only;
-- delete moves an entry into the recycle bin instead of erasing it (mirrors the
-- tp_skill.deleted precedent, V77), so the assembly read point filters deleted = 0
-- and restored entries come back with their original inject_status.
ALTER TABLE tp_ai_ctx_memory ADD COLUMN IF NOT EXISTS deleted SMALLINT NOT NULL DEFAULT 0;
CREATE INDEX IF NOT EXISTS idx_ai_ctx_memory_recycle ON tp_ai_ctx_memory (project_id, id) WHERE deleted = 1;
COMMENT ON COLUMN tp_ai_ctx_memory.deleted IS 'Soft-delete flag 0=active 1=recycle bin (ledger governed by AP T449, mirrors tp_skill.deleted)';

-- ################ V362__document_lineage_group.sql ################
-- document lineage chain: rows sharing one logical document
-- (project + display name + file type) belong to one lineage group so that the
-- sha256 duplicate gate becomes group-scoped — re-uploading identical content
-- inside the same lineage is refused, identical content under a different name
-- is admitted as a separate document (anti-duplicate and anti-iteration no
-- longer fight). lineage_group_id = root document id of the group; the service
-- layer guarantees the value for new rows (first member self-references after
-- insert), therefore the column stays nullable at DB level by design.
ALTER TABLE tp_document ADD COLUMN lineage_group_id BIGINT;

UPDATE tp_document d
   SET lineage_group_id = g.root_id
  FROM (SELECT MIN(id) AS root_id, project_id, name, file_type
          FROM tp_document
         GROUP BY project_id, name, file_type) g
 WHERE d.project_id = g.project_id
   AND d.name = g.name
   AND d.file_type = g.file_type;

CREATE INDEX IF NOT EXISTS idx_tp_document_lineage_group
    ON tp_document (lineage_group_id);

ALTER TABLE tp_document DROP CONSTRAINT tp_document_file_hash_key;

ALTER TABLE tp_document
    ADD CONSTRAINT tp_document_lineage_hash_unique
    UNIQUE (lineage_group_id, file_hash);

-- ################ V363__chat_draft_system_origin_and_memory_pending_state.sql ################
-- Migration: open the draft ledger to system-originated proposals and restore the
-- memory pending-confirmation state (plan-A re-adjudication 11-03, ).
-- Semantics:
--   * tp_ai_chat_draft gains the system-origin shape: a distilled project-memory
--     proposal is minted by ai-service with NO dialog session and NO owning
--     message, so session_id/message_id relax to NULL-able. The confirmation
--     guard reads project_id for the system branch (membership + TP_PROJECT_MEMORY
--     permission behind the door); dialog drafts keep deriving the project from
--     the session through requireOwned, exactly as before (22-kind shared chain).
--   * tp_ai_ctx_memory: inject_status gains 2 = awaiting human confirmation
--     (the draft gate re-opened). Assembly reads inject_status=1 AND deleted=0,
--     so a pending entry is never injected — the "only active states inject"
--     contract holds without touching the read point.
-- Execution: manual psql (Flyway not enabled):
--   set -a; source .env; docker exec -i -e PGPASSWORD="$DB_PASSWORD" testpike-postgres \
--     psql -U *** -d testpike -f - < this file
--   then re-run tools/ops/gen_schema_init.sh

ALTER TABLE tp_ai_chat_draft ALTER COLUMN session_id DROP NOT NULL;
ALTER TABLE tp_ai_chat_draft ALTER COLUMN message_id DROP NOT NULL;
ALTER TABLE tp_ai_chat_draft ADD COLUMN IF NOT EXISTS project_id BIGINT;

COMMENT ON COLUMN tp_ai_chat_draft.session_id IS 'Owning dialog session (NULL = system-originated draft with no conversation, e.g. distilled project memory); the confirmation guard branches on this nullness: session drafts check ownership, system drafts check project membership';
COMMENT ON COLUMN tp_ai_chat_draft.message_id IS 'The draft frame''s owning message (UNIQUE: one message mints at most one confirmable draft; NULL = system-originated draft not tied to any dialog message)';
COMMENT ON COLUMN tp_ai_chat_draft.project_id IS 'Owning project for system-originated drafts (guard-checked for membership before the door opens); NULL for dialog drafts whose project is derived from the session';

COMMENT ON COLUMN tp_ai_ctx_memory.inject_status IS '2 = distilled but awaiting human confirmation through the draft gate (never injected), 1 = active and eligible for assembly injection, 0 = operator-disabled through the ledger view';

-- ################ V364__ai_api_access_governance.sql ################
-- Migration: governance overlay and switches for the dialog pass-through door.
--
-- Why this table exists:
--   The catalog of callable endpoints is generated from the live request mappings, so nobody has
--   to register a tool row per capability any more. Generation can decide everything that is
--   structurally knowable (HTTP method, path shape, declared parameters, whether the endpoint
--   carries a project anchor). It cannot decide two things, and those two are the whole content of
--   this table:
--     1) an endpoint that carries no project anchor may still be safe to expose — that is a human
--        judgement, so it needs an explicit row with scope_verified = 1 to become reachable
--        (absent row = unreachable, fail-closed);
--     2) an endpoint that is cataloged but should not be served by the dialog (retired, or awaiting
--        a decision) is turned off here, with the reason kept next to it so a rejection reads as
--        a registered decision instead of a silent gap.
--   Red line carried from the tool surface: nothing in this table grants privilege. The scope guard
--   in the service still checks the acting operator against project membership on every anchored
--   call; this overlay only ever narrows the reachable set, never widens the identity rules.
--
-- Flyway is not wired in this project: apply manually against the target database (DBA path in
-- production), then regenerate db/schema-init.sql with scripts/gen_schema_init.sh so a fresh
-- install carries the same shape.

CREATE TABLE IF NOT EXISTS tp_ai_api_access_governance (
    id BIGSERIAL PRIMARY KEY,
    endpoint_key VARCHAR(200) NOT NULL,
    scope_verified SMALLINT NOT NULL DEFAULT 0,
    reachable SMALLINT NOT NULL DEFAULT 1,
    ai_desc VARCHAR(500),
    exclude_reason VARCHAR(300),
    created_at TIMESTAMP NOT NULL DEFAULT now(),
    updated_at TIMESTAMP NOT NULL DEFAULT now()
);

CREATE UNIQUE INDEX IF NOT EXISTS uq_ai_api_access_governance_key
    ON tp_ai_api_access_governance (endpoint_key);

COMMENT ON TABLE tp_ai_api_access_governance IS
    'Governance overlay of the dialog pass-through door: human verdicts the generated catalog cannot derive';
COMMENT ON COLUMN tp_ai_api_access_governance.endpoint_key IS
    'Catalog key, format "HTTP-METHOD /path/pattern" (generated catalog is the authority on existence)';
COMMENT ON COLUMN tp_ai_api_access_governance.scope_verified IS
    '1 = verified that this anchor-less endpoint does not leak across projects; 0 = unreachable through the door';
COMMENT ON COLUMN tp_ai_api_access_governance.reachable IS
    '0 = retired from the door while keeping the catalog entry (an audit-visible decision, not a deletion)';
COMMENT ON COLUMN tp_ai_api_access_governance.ai_desc IS
    'What this endpoint answers, written for the dialog reader; blank falls back to a path-derived label';
COMMENT ON COLUMN tp_ai_api_access_governance.exclude_reason IS
    'Why the endpoint is out of reach; shown on rejection instead of silence';

