-- ################ V446__ai_repair_default_open.sql ################
-- Flip the failed-case auto-repair master switch to the shipped default "on".
-- Every AI-driven feature switch is enabled out of the box so a fresh install
-- needs zero configuration; the off-state path keeps its honest guidance
-- behaviour (rejection carries the settings location and the parameter name).
-- Idempotent: only rows still holding a factory-off value are touched, user
-- settings stored in any other form are left as they are.
UPDATE tp_sys_config
SET config_value = '1'
WHERE config_key = 'ai.repair.enabled'
  AND config_value IN ('0', 'false');

INSERT INTO tp_sys_config (config_key, config_value, group_name, value_type, encrypt_flag, description)
SELECT 'ai.repair.enabled', '1', '系统', 'int', 0,
       '失败自动修复主开关（默认开启；关闭后不再产生修复提案，也不改动脚本版本；仅支持 0/1，在本页打开即时生效）'
WHERE NOT EXISTS (SELECT 1 FROM tp_sys_config WHERE config_key = 'ai.repair.enabled');

-- ################ V447__ai_default_open_description_realign.sql ################
-- Migration: realign shipped AI switch descriptions with their default-open values.
--
-- Why this file exists:
--   The default-open batch raised the factory values of the AI feature
--   switches to "on" but several tp_sys_config.description literals still
--   advertised the old factory-off state, and a small number of databases may
--   still hold the pre-batch value. Operators read these descriptions on the
--   settings page, so a stale claim is wrong operational information: the
--   text must state the shipped default, what the switch does, and what
--   happens when it is off. Idempotent: every statement only touches rows
--   whose value/description actually drifted, so re-running changes nothing.
UPDATE tp_sys_config
SET description = '对话启动回归演练批次的开关（默认开启；启动仍需本项目在编号列表内，且每次启动都要人工点击确认才会执行；关闭后对话不再发起演练批次；在「系统设置」中修改）'
WHERE config_key = 'ai.chat.rehearsal-run.enabled'
  AND description IS DISTINCT FROM '对话启动回归演练批次的开关（默认开启；启动仍需本项目在编号列表内，且每次启动都要人工点击确认才会执行；关闭后对话不再发起演练批次；在「系统设置」中修改）';
UPDATE tp_sys_config
SET description = '文档分段摘要缓存开关（默认开启；同一文档重新提取时复用已生成的分段摘要，不再重复逐段归纳；文档内容更新后缓存自动失效；关闭后每次提取重新逐段归纳）'
WHERE config_key = 'ai.ctx.doc-summaries-cache'
  AND description IS DISTINCT FROM '文档分段摘要缓存开关（默认开启；同一文档重新提取时复用已生成的分段摘要，不再重复逐段归纳；文档内容更新后缓存自动失效；关闭后每次提取重新逐段归纳）';
UPDATE tp_sys_config
SET description = '失败归因主开关（默认开启；关闭后失败不再调用模型归因、也不写入归因结果；仅支持 0/1，在本页打开即时生效）'
WHERE config_key = 'ai.classify.enabled'
  AND description IS DISTINCT FROM '失败归因主开关（默认开启；关闭后失败不再调用模型归因、也不写入归因结果；仅支持 0/1，在本页打开即时生效）';
UPDATE tp_sys_config
SET description = '失败自动修复主开关（默认开启；关闭后不再产生修复提案，也不改动脚本版本；仅支持 0/1，在本页打开即时生效）'
WHERE config_key = 'ai.repair.enabled'
  AND description IS DISTINCT FROM '失败自动修复主开关（默认开启；关闭后不再产生修复提案，也不改动脚本版本；仅支持 0/1，在本页打开即时生效）';
-- Heal any database that still carries the pre-batch factory-off value.
UPDATE tp_sys_config
SET config_value = 'true'
WHERE config_key = 'ai.chat.rehearsal-run.enabled'
  AND config_value IN ('0', 'false');
UPDATE tp_sys_config
SET config_value = 'true'
WHERE config_key = 'ai.ctx.doc-summaries-cache'
  AND config_value IN ('0', 'false');
UPDATE tp_sys_config
SET config_value = '1'
WHERE config_key = 'ai.classify.enabled'
  AND config_value IN ('0', 'false');
UPDATE tp_sys_config
SET config_value = '1'
WHERE config_key = 'ai.repair.enabled'
  AND config_value IN ('0', 'false');
-- The table comment in the cache-creation migration claimed the switch ships
-- off; the dictionary on live databases is corrected here and the source file
-- carries the fixed text for fresh installs.
COMMENT ON TABLE tp_doc_summary_cache IS
    'Generation-keyed cache of Map/Reduce group summaries for document extraction (AP-1 side (3); switch ai.ctx.doc-summaries-cache, default on)';

-- ################ V448__ai_limit_default_wording_realign.sql ################
-- Migration: realign capability-limit descriptions with their pinned defaults.
--
-- Why this file exists:
--   The capability-limit pinning batch raised the shipped values of ten AI
--   numeric keys (wide defaults so real tasks are not truncated) but their
--   settings-page descriptions still advertised the old narrow number.
--   Operators read the description as the factory default, so a stale
--   "default N" claim is wrong operational information. Values are correct
--   and stay untouched; only description wording follows the value here.
--   Idempotent: each statement only fires while the description differs.

UPDATE tp_sys_config
SET description = '对话首帧等待预算秒数（默认 30；区间 2~30，热更即生效；预算内未收到首个响应帧时连接以错误提示结束，不会无限等待）'
WHERE config_key = 'ai.chat.first-frame-budget-seconds'
  AND description IS DISTINCT FROM '对话首帧等待预算秒数（默认 30；区间 2~30，热更即生效；预算内未收到首个响应帧时连接以错误提示结束，不会无限等待）';

UPDATE tp_sys_config
SET description = '单次回答最多引用的来源材料条数（默认 8；区间 1~10，热更即生效；超出数量的检索结果不会出现在回答的来源清单里）'
WHERE config_key = 'ai.chat.grounding.max-citations'
  AND description IS DISTINCT FROM '单次回答最多引用的来源材料条数（默认 8；区间 1~10，热更即生效；超出数量的检索结果不会出现在回答的来源清单里）';

UPDATE tp_sys_config
SET description = '单条对话问题的图片附件上限（默认 8 张；超出时发送会被拒绝并提示本次张数与上限，改此值即时生效）'
WHERE config_key = 'ai.chat.image.max-attachments'
  AND description IS DISTINCT FROM '单条对话问题的图片附件上限（默认 8 张；超出时发送会被拒绝并提示本次张数与上限，改此值即时生效）';

UPDATE tp_sys_config
SET description = '单条提问最多引用的对象数量（默认 20；区间 1~20，热更即生效；超出数量时提问会被拒绝并提示当前引用个数，不会悄悄丢掉一部分）'
WHERE config_key = 'ai.chat.ref.max-objects'
  AND description IS DISTINCT FROM '单条提问最多引用的对象数量（默认 20；区间 1~20，热更即生效；超出数量时提问会被拒绝并提示当前引用个数，不会悄悄丢掉一部分）';

UPDATE tp_sys_config
SET description = '单个对话会话的 token 预算上限（默认 2000000，热更即生效；会话内累计用量超出后本轮不再继续调用模型，用量中心可查已消耗部分）'
WHERE config_key = 'ai.chat.session-budget-tokens'
  AND description IS DISTINCT FROM '单个对话会话的 token 预算上限（默认 2000000，热更即生效；会话内累计用量超出后本轮不再继续调用模型，用量中心可查已消耗部分）';

UPDATE tp_sys_config
SET description = '注入回答的项目记忆条目数上限（默认 128；区间 1~200，在本页修改即时生效；条目超出上限时按与本次提问的相关性取舍，不会整批拼入上下文）'
WHERE config_key = 'ai.ctx.memory-max-items'
  AND description IS DISTINCT FROM '注入回答的项目记忆条目数上限（默认 128；区间 1~200，在本页修改即时生效；条目超出上限时按与本次提问的相关性取舍，不会整批拼入上下文）';

UPDATE tp_sys_config
SET description = '对话上下文保留的最近轮数（默认 20；区间 1~50，在本页修改即时生效；比这更早的历史自动折叠为一段摘要随每轮提供，长对话不会因此丢掉近期内容）'
WHERE config_key = 'ai.ctx.session-keep-recent-turns'
  AND description IS DISTINCT FROM '对话上下文保留的最近轮数（默认 20；区间 1~50，在本页修改即时生效；比这更早的历史自动折叠为一段摘要随每轮提供，长对话不会因此丢掉近期内容）';

UPDATE tp_sys_config
SET description = '工具执行结果单次入袋的 token 预算（默认 8000；区间 200~20000，在本页修改即时生效；超出预算的长结果自动改为头尾摘录+全文落盘可检索，回答照常给出，不会整段丢失）'
WHERE config_key = 'ai.ctx.tool-block-max-tokens'
  AND description IS DISTINCT FROM '工具执行结果单次入袋的 token 预算（默认 8000；区间 200~20000，在本页修改即时生效；超出预算的长结果自动改为头尾摘录+全文落盘可检索，回答照常给出，不会整段丢失）';

UPDATE tp_sys_config
SET description = '探索访问页面上限（默认 64；无进展/预算终止判据）'
WHERE config_key = 'ai.explore.max-pages'
  AND description IS DISTINCT FROM '探索访问页面上限（默认 64；无进展/预算终止判据）';

UPDATE tp_sys_config
SET description = '探索单次最大步数上限（默认 128；预算快照来源）'
WHERE config_key = 'ai.explore.max-steps'
  AND description IS DISTINCT FROM '探索单次最大步数上限（默认 128；预算快照来源）';

