-- ################ V502__session_login_state_ledger.sql ################
-- Migration: session login-state ledger foundation .
-- Gives the credential vault honest lifecycle columns and creates the
-- login-state ledger table that references it.
-- tp_credential gains three nullable columns (source_kind / expires_at /
-- last_verified_at). Every existing row keeps NULL = legacy manual-registration
-- shape, so all current read paths are untouched (zero-drift guarantee booked
-- in the acceptance row; the source_kind=1 backfill is a batch-tail
-- ledger action, not this migration).
-- Scope note (D11 ruling): the origin scope lives ONLY on tp_login_state
-- (scope_origins jsonb list). tp_credential deliberately gets no scope column
-- — keeping the same fact in two tables is a drift source.
-- tp_login_state = one row per captured/renewed login state of one account:
-- unique (project_id, state_name); re-capture under the same name updates the
-- row (a login state is consumable — renewal is an update, never an append);
-- different accounts = different state_name rows. Ciphertext stays single-sourced
-- in tp_credential.secret_cipher via credential_id (no second vault).
-- Usage: docker exec -i testpike-postgres psql -U testpike -d testpike -f - < db/migration/V502__session_login_state_ledger.sql
ALTER TABLE tp_credential ADD COLUMN IF NOT EXISTS source_kind SMALLINT;
ALTER TABLE tp_credential ADD COLUMN IF NOT EXISTS expires_at TIMESTAMP;
ALTER TABLE tp_credential ADD COLUMN IF NOT EXISTS last_verified_at TIMESTAMP;

COMMENT ON COLUMN tp_credential.source_kind IS 'Credential provenance: 1=manually registered 2=produced by a login chain 3=captured from a browser session; NULL=legacy row (shape before this column existed)';
COMMENT ON COLUMN tp_credential.expires_at IS 'Absolute expiry when it could be parsed (JWT exp claim / cookie Expires); NULL=expiry unknown, the state light shows "validity unknown" instead of guessing';
COMMENT ON COLUMN tp_credential.last_verified_at IS 'Last server-side verification outcome timestamp; consumption hits 401/403 mark the row invalid (AV3 trigger three)';

CREATE TABLE IF NOT EXISTS tp_login_state (
    id               BIGSERIAL    PRIMARY KEY,
    project_id       BIGINT       NOT NULL REFERENCES tp_project (id),
    state_name       VARCHAR(200) NOT NULL,
    role_scope       VARCHAR(64),
    account_label    VARCHAR(200),
    kind             VARCHAR(32)  NOT NULL,
    credential_id    BIGINT       REFERENCES tp_credential (id),
    state_object_key VARCHAR(500),
    scope_origins    JSONB        NOT NULL DEFAULT '[]'::jsonb,
    source_kind      SMALLINT     NOT NULL DEFAULT 3,
    expires_at       TIMESTAMP,
    last_verified_at TIMESTAMP,
    status           SMALLINT     NOT NULL DEFAULT 1,
    remark           VARCHAR(500),
    created_at       TIMESTAMP    NOT NULL DEFAULT now(),
    updated_at       TIMESTAMP    NOT NULL DEFAULT now(),
    CONSTRAINT uq_login_state_name UNIQUE (project_id, state_name),
    CONSTRAINT ck_login_state_kind CHECK (kind IN ('token', 'storage_state', 'cookie_set'))
);

COMMENT ON TABLE tp_login_state IS 'Login-state ledger (AV2): one row per account login state captured or produced for a project; secret material stays in tp_credential (single vault), snapshots ride MinIO state_object_key scoped to the project';
COMMENT ON COLUMN tp_login_state.state_name IS 'Human-readable state name, unique per project; re-capture under the same name updates the row, new accounts get new names';
COMMENT ON COLUMN tp_login_state.role_scope IS 'Test-role dimension (role-level sharing is the default granularity, D1 ruling); resolution by role with multiple un-disambiguated rows fails closed and lists candidates';
COMMENT ON COLUMN tp_login_state.account_label IS 'Account label (e.g. "approver A") — disambiguation slot when one role has several accounts';
COMMENT ON COLUMN tp_login_state.kind IS 'State shape: token=bearer value, storage_state=full Playwright storageState snapshot, cookie_set=cookie pairs; SSO redirect chains default-recommend storage_state (keeps the silent re-login chain, D11)';
COMMENT ON COLUMN tp_login_state.credential_id IS 'FK into tp_credential — the ciphertext single source (no second vault, D3 ruling)';
COMMENT ON COLUMN tp_login_state.state_object_key IS 'MinIO object key of the storageState snapshot (project-level scope; NULL for non-snapshot kinds)';
COMMENT ON COLUMN tp_login_state.scope_origins IS 'Origin whitelist as a jsonb list (D11: SSO chains spread state over target-system + IdP domains; reading outside the list is refused fail-closed)';
COMMENT ON COLUMN tp_login_state.source_kind IS 'Provenance mirror of tp_credential.source_kind: 2=login chain output 3=browser capture (ledger rows are never manual)';
COMMENT ON COLUMN tp_login_state.status IS '1=enabled 0=disabled (managed via perm:session:manage; disabling takes effect from the next session, never cuts running sessions)';

CREATE INDEX IF NOT EXISTS ix_login_state_project
    ON tp_login_state (project_id, status);
CREATE INDEX IF NOT EXISTS ix_login_state_credential
    ON tp_login_state (credential_id);

-- ################ V503__judge_density_floor_recalibration.sql ################
-- Migration: re-adjudicate the judge-domain recall-density floor from the third
-- calibration window , and settle the
-- scenario-domain gate wording with the measured row-shape evidence.
-- Terminal evidence, all through the real chain (result file booked 03:28:36):
--   judge: 2074 items over an estimated 65546 tokens = 31.64 per k-token,
-- finished inside its segment (escape=false). The previous calibration
--     measured 34.39 on the same golden input; two runs on identical input
--     differ by ~8%, so the lower bound is taken to avoid false rejections
--     of healthy question-gen: floor = 31.64 x 0.6 = 19.0 (was 20.6).
--   scenario: row-shape evidence booked (row_id 127, batch 9030277): one
--     preview row carries the whole scenario set (8 entries) for a 40000
--     character requirement sample, so counting rows per k-token yields 0.03
--     and is not comparable with the per-entry domains. Floor stays 0
--     (gate off) and the description now records this as a measured shape
--     finding, not a pending calibration.
--   spec: 200 items over 10162 estimated tokens = 19.68, matching the V500
--     calibration figure exactly -> 11.8 re-confirmed, no change (the leg
--     escaped its sub-window with document status still pending; the booked
--     item count is persisted output, accepted as re-confirmation only).
--   mock: 540 items over 15975 estimated tokens = 33.8 -> 20.3 unchanged.
-- Values stay inside 0~50.
-- Usage: docker exec -i testpike-postgres psql -U testpike -d testpike -f - < db/migration/V503__judge_density_floor_recalibration.sql
INSERT INTO tp_sys_config (config_key, config_value, group_name, value_type, encrypt_flag, description) VALUES
    ('ai.judge.recall-density-floor-per-ktoken', '19.0', '系统', 'string', 0, '评测集造题的每千 token 产出条数下限（默认 19.0，允许 0~50，填 0 表示关闭该校验）。分母为估算 token 数（按字符数×0.75 折算，非计费 token）；标定值来自需求文档样张造题终态实测 31.64 条/千 token×0.6 安全系数（同输入两次实测 34.39 与 31.64，波动约 8%，取低值防止误拒正常产出）。值超出 0~50 区间或不是数字时保存会被拒绝，配置缺失或非法时按默认值 19.0 执行。保存即生效，无需重启）'),
    ('ai.gen.scenario-recall-density-floor-per-ktoken', '0', '系统', 'string', 0, '场景枚举的每千 token 产出条数下限（当前 0=该校验不启用：实测一行样张（40000 字符需求段）产出一整组场景条目，按行数折算的密度与其它按条计数的功能不可比，暂不启用该校验。允许 0~50，值超出区间或不是数字时保存会被拒绝。保存即生效，无需重启）')
ON CONFLICT (config_key) DO UPDATE SET config_value = EXCLUDED.config_value,
    description = EXCLUDED.description;

-- ################ V504__session_k8_governance_keys.sql ################
-- Migration: AV batch K8 governance keys for the login-state capture chain
-- . Five hot-update knobs seeded as configuration rows so no
-- consumer hardcodes a window; the reader side (SessionGovernanceKeys) falls
-- back to the factory defaults mirrored there when a value is blank or
-- illegal, and a non-positive retention window refuses the cleanup sweep
-- instead of purging everything.
-- Usage: docker exec -i testpike-postgres psql -U testpike -d <slot-db> -f - < db/migration/V504__session_k8_governance_keys.sql
INSERT INTO tp_sys_config (config_key, config_value, group_name, value_type, encrypt_flag, description) VALUES
    ('session.capture-timeout-minutes', '10', '系统', 'string', 0, '采集会话窗口上限（分钟，默认 10，允许 1~240）。从发起采集到勾选确认入册的全部操作时长超过该值时，本次采集会话作废并提示重新发起。保存即生效，无需重启）'),
    ('session.validate-timeout-ms', '8000', '系统', 'string', 0, '执行机侧有效性试请求的超时时间（毫秒，默认 8000，允许 500~60000）。请求超时按核验未通过处理，状态灯标明原因。保存即生效，无需重启'),
    ('session.renew-lead-minutes', '15', '系统', 'string', 0, '到期提醒提前量（分钟，默认 15，允许 0~1440）。登录态剩余有效期小于该值时，状态灯从「有效」转为「即将到期」。保存即生效，无需重启'),
    ('session.retention-days', '30', '系统', 'string', 0, '失效条目保留天数（默认 30，允许 1~365）。状态为失效且超过该天数的登录态条目，每日 04:30 清理其账本行；对应密文仅在该凭据由采集产生且无其他条目引用时一并删除，手工登记的凭据行不受影响。填 0 或负数时清理不执行（全量保留）。保存即生效，无需重启'),
    ('session.headless-host-capture.enabled', '0', '系统', 'string', 0, '执行机采集窗开关（1=开启，0=关闭，默认关闭）。关闭时如需在执行机上采集登录态，页面会提示改用本机浏览器直连采集；开启前需执行机已部署图形采集环境。修改入口：系统设置 → 配置管理，参数名称 session.headless-host-capture.enabled')
ON CONFLICT (config_key) DO NOTHING;

-- ################ V505__replay_relaxed_context_defaults.sql ################
-- Replay the factory defaults of four context/stream keys whose caps were
-- relaxed in the seed line only: live databases kept the old, narrower values
-- while new installs already received the relaxed ones, so dev environments
-- ran tighter than the shipped defaults (defect ledger, scan).
-- Values and the on-screen description text are pinned to the seed state in
-- one statement; the IS DISTINCT FROM guard keeps replay a no-op once the
-- row already matches, so re-running this file writes nothing.
UPDATE tp_sys_config AS t
SET config_value = s.v,
    description  = s.d
FROM (VALUES
    ('ai.chat.first-frame-budget-seconds', '30',
     '对话首帧等待预算秒数（默认 30；区间 2~30，热更即生效；预算内未收到首个响应帧时连接以错误提示结束，不会无限等待）'),
    ('ai.ctx.memory-max-items', '128',
     '注入回答的项目记忆条目数上限（默认 128；区间 1~200，在本页修改即时生效；条目超出上限时按与本次提问的相关性取舍，不会整批拼入上下文）'),
    ('ai.ctx.session-keep-recent-turns', '20',
     '对话上下文保留的最近轮数（默认 20；区间 1~50，在本页修改即时生效；比这更早的历史自动折叠为一段摘要随每轮提供，长对话不会因此丢掉近期内容）'),
    ('ai.ctx.tool-block-max-tokens', '8000',
     '工具执行结果单次入袋的 token 预算（默认 8000；区间 200~20000，在本页修改即时生效；超出预算的长结果自动改为头尾摘录+全文落盘可检索，回答照常给出，不会整段丢失）')
) AS s(k, v, d)
WHERE t.config_key = s.k
  AND (t.config_value IS DISTINCT FROM s.v OR t.description IS DISTINCT FROM s.d);

