-- ################ V548__mcp_doc_max_bytes_key.sql ################
-- V548__mcp_doc_max_bytes_key.sql — byte-ceiling governance key for the MCP document channel.
-- Seeds mcp.doc.max-bytes (factory default 33554432 bytes = 32 MiB), the per-upload
-- ceiling enforced by RestMcpToolGateway.docUpload before any write hop: an oversized
-- upload is refused with the current size, the ceiling and this key's literal in the
-- message, so the operator knows both what happened and where to adjust it. The value
-- is hot-updatable through tp_sys_config; the gateway reads it live on every request
-- via RestCoreConfigClient, so changing the cap takes effect without a restart.
-- The shipped default stays in sync with DEFAULT_DOC_MAX_BYTES on the gateway class
-- (the fallback constant is the same number — drift between them is a defect).
-- Idempotent replay.
INSERT INTO tp_sys_config (config_key, config_value, group_name, value_type, encrypt_flag, description) VALUES
('mcp.doc.max-bytes', '33554432', '系统', 'int', 0, 'MCP 文档通道单次上传大小上限（字节，默认 33554432 即 32MB；超限的上传会被拒绝并提示当前大小与上限，如需更大额度请调整本键）')
ON CONFLICT (config_key) DO NOTHING;

-- ################ V549__mcp_gen_max_requirements_key.sql ################
-- V549__mcp_gen_max_requirements_key.sql — count-ceiling governance key for the MCP generation trigger.
-- Seeds mcp.gen.max-requirements (factory default 200), the per-call ceiling over
-- requirement ids enforced by RestMcpToolGateway.genCasesFromRequirement before any
-- queue hop: an oversized selection is refused with the current count, the ceiling
-- and this key's literal in the message, so the caller knows both what happened and
-- where to adjust it. The value is hot-updatable through tp_sys_config; the gateway
-- reads it live on every request via RestCoreConfigClient, so changing the cap takes
-- effect without a restart. The shipped default stays in sync with
-- DEFAULT_GEN_MAX_REQUIREMENTS on the gateway class (drift between them is a defect).
-- Idempotent replay.
INSERT INTO tp_sys_config (config_key, config_value, group_name, value_type, encrypt_flag, description) VALUES
('mcp.gen.max-requirements', '200', '系统', 'int', 0, 'MCP 生成触发单次需求点数量上限（默认 200；超限的触发会被拒绝并提示当前数量与上限，如需更大额度请调整本键）')
ON CONFLICT (config_key) DO NOTHING;

-- ################ V550__web_element_anchor_stat.sql ################
-- V550__web_element_anchor_stat.sql — per-(viewport, anchor-type) anchor hit
-- ledger statistics (WE batch S1 . The executor reports one outcome
-- row per ordered anchor try (03 2.4 result trailing key elementAnchorHits);
-- core keeps counts columnar per bucket+type so a desktop hit can never
-- inflate a broken mobile anchor (design §8 columnar rule, two-weights
-- discipline), and recomputes tp_web_element.confidence as the smoothed hit
-- rate (hits + w/2) / (hits + misses + w) — prior weight w from the hot key
-- below; prior mean 0.5 equals the ledger's neutral starting confidence, so
-- young rows without feedback keep their 0.5. R57: rows are bounded by the
-- element FK (ON DELETE CASCADE) — retiring an element drops its stat rows.
CREATE TABLE IF NOT EXISTS tp_web_element_anchor_stat (
    element_id  BIGINT       NOT NULL REFERENCES tp_web_element (id) ON DELETE CASCADE,
    viewport    VARCHAR(32)  NOT NULL,
    anchor_type VARCHAR(32)  NOT NULL,
    hits        BIGINT       NOT NULL DEFAULT 0,
    misses      BIGINT       NOT NULL DEFAULT 0,
    updated_at  TIMESTAMP    NOT NULL DEFAULT now(),
    CONSTRAINT pk_web_element_anchor_stat PRIMARY KEY (element_id, viewport, anchor_type),
    CONSTRAINT ck_anchor_stat_hits CHECK (hits >= 0),
    CONSTRAINT ck_anchor_stat_misses CHECK (misses >= 0)
);

COMMENT ON TABLE tp_web_element_anchor_stat IS 'Anchor hit/miss counts per (element, viewport bucket, anchor type), fed by executor result relays (WE slice 3b).';
COMMENT ON COLUMN tp_web_element_anchor_stat.viewport IS 'Execution bucket label (e.g. 1440x900); columnar accounting keeps buckets from mixing.';
COMMENT ON COLUMN tp_web_element_anchor_stat.anchor_type IS 'Anchor class tried (css|xpath|text|placeholder|alt|testid|rel); __truncated__ sentinel rows are never stored.';

-- Hot-updatable smoothing prior (idempotent replay; tp_sys_config is the live source).
INSERT INTO tp_sys_config (config_key, config_value, group_name, value_type, encrypt_flag, description) VALUES
('element.confidence-smooth-prior-weight', '4', '系统', 'int', 0, '页面元素库置信度的平滑权重（取值范围 0-1000；数值越大历史先验影响越久，数值越小近期命中与失手越快改变置信度；置信度=按该权重平滑后的命中率，无人工反馈时保持缺省 0.5）')
ON CONFLICT (config_key) DO NOTHING;

-- ################ V551__web_element_repair_suggestion.sql ################
-- V551__web_element_repair_suggestion.sql — Web-shape element repair suggestions
-- (WE batch S2 . The A9 suggestion board gains an object dimension:
--   * APP rows keep proposing a step-target patch inside one case script;
--   * WEB rows propose a replacement locator anchor for one tp_web_element
--     entry, so one approved anchor fix serves every referencing case
--     (design 2.3 red line: equivalent re-location only, never an action edit).
-- Column defaults keep every existing row and caller on the APP shape
-- (zero migration, zero drift on the A9 board).
ALTER TABLE tp_appauto_step_suggestion ADD COLUMN IF NOT EXISTS object_type VARCHAR(8) NOT NULL DEFAULT 'APP';
ALTER TABLE tp_appauto_step_suggestion ADD COLUMN IF NOT EXISTS element_id BIGINT NULL;
ALTER TABLE tp_appauto_step_suggestion ADD COLUMN IF NOT EXISTS adopted_element_revision INT NULL;

-- WEB rows carry no action change, so proposed_action turns nullable and the
-- per-dimension shape rule moves into one paired CHECK (single gate, DB side).
ALTER TABLE tp_appauto_step_suggestion ALTER COLUMN proposed_action DROP NOT NULL;

ALTER TABLE tp_appauto_step_suggestion DROP CONSTRAINT IF EXISTS ck_step_suggestion_object_type;
ALTER TABLE tp_appauto_step_suggestion ADD CONSTRAINT ck_step_suggestion_object_type
    CHECK (object_type IN ('APP', 'WEB'));

ALTER TABLE tp_appauto_step_suggestion DROP CONSTRAINT IF EXISTS ck_step_suggestion_shape;
ALTER TABLE tp_appauto_step_suggestion ADD CONSTRAINT ck_step_suggestion_shape CHECK (
    (object_type = 'APP' AND proposed_action IS NOT NULL AND proposed_target IS NOT NULL)
    OR (object_type = 'WEB' AND element_id IS NOT NULL AND proposed_target IS NOT NULL));

-- Provenance domain gains the Web-family value "dom" (anchor rebuilt from a
-- fresh DOM snapshot after a redesign). Java single source =
-- AppautoAiSampleServiceImpl.HIT_SOURCES; the sample board column hit_source
-- carries no DB CHECK (domain is service-side only), so only the suggestion
-- table CHECK is extended here.
ALTER TABLE tp_appauto_step_suggestion DROP CONSTRAINT IF EXISTS ck_appauto_step_suggestion_source;
ALTER TABLE tp_appauto_step_suggestion ADD CONSTRAINT ck_appauto_step_suggestion_source
    CHECK (source IN ('vision', 'a11y', 'cache', 'manual', 'dom'));

COMMENT ON COLUMN tp_appauto_step_suggestion.object_type IS 'Object dimension: APP step-target patch / WEB element anchor replacement (WE S2)';
COMMENT ON COLUMN tp_appauto_step_suggestion.element_id IS 'WEB rows: target tp_web_element id (soft reference, no FK, same posture as case_id)';
COMMENT ON COLUMN tp_appauto_step_suggestion.adopted_element_revision IS 'WEB rows: ledger revision after the approved anchor was merged in (optimistic-lock trail, mirrors adopted_script_version)';

-- Board queries now filter by dimension; keep the old case board index untouched.
CREATE INDEX IF NOT EXISTS ix_appauto_step_suggestion_object_board
    ON tp_appauto_step_suggestion (project_id, object_type, status, created_at DESC);

-- auto-apply when strong anchor equivalence AND the visual similarity of the
-- hit screenshot against the ledger evidence crop both pass; this key is the
-- similarity floor. Consumed by the dispatch envelope (WE .
INSERT INTO tp_sys_config (config_key, config_value, group_name, value_type, encrypt_flag, description) VALUES
('element.re-anchor.similarity-floor', '0.85', '系统', 'string', 0, '自动直更新锚所需的视觉相似度下限（默认 0.85，取值范围 0~1，填 1 表示禁止一切自动直更、全部走元素修复建议单）。重锚命中元素截图与基线裁剪区相似度达到该值且锚身份等价两项同时满足才免批直更，任一项不足一律出建议单等人工批准；值超出 0~1 或不是数字时保存会被拒绝，配置缺失或非法时按默认 0.85 执行；保存即生效，无需重启')
ON CONFLICT (config_key) DO NOTHING;

-- ################ V552__test_case_evidence_grade.sql ################
-- V552__test_case_evidence_grade.sql — evidence grade for off-agent script write-back.
-- The MCP tool script.writeback records how much proof a case script carries:
--   0 = no evidence on file (default; every pre-existing row lands here),
--   1 = off-platform self-report without an evidence package,
--   2 = off-platform evidence package recorded,
--   3 = platform trial-run re-validation passed.
-- Existing rows keep 0 through the column default only; no backfill UPDATE is
-- issued, so historical rows are never rewritten retroactively.
ALTER TABLE tp_test_case ADD COLUMN IF NOT EXISTS evidence_grade SMALLINT NOT NULL DEFAULT 0;

ALTER TABLE tp_test_case DROP CONSTRAINT IF EXISTS ck_test_case_evidence_grade;
ALTER TABLE tp_test_case ADD CONSTRAINT ck_test_case_evidence_grade
    CHECK (evidence_grade IN (0, 1, 2, 3));

COMMENT ON COLUMN tp_test_case.evidence_grade IS
    'Evidence grade of the current script revision: 0=none, 1=off-platform self-report, 2=evidence package on file, 3=platform re-validation passed';

-- ################ V553__mcp_confirm_ttl_seconds_key.sql ################
-- V553__mcp_confirm_ttl_seconds_key.sql — validity window key for the MCP in-session confirmation loop.
-- Seeds mcp.confirm.ttl-seconds (factory default 1800), the one-shot lifetime of a
-- confirm_ref issued by an MCP write tool that hit the human-confirmation gate. The
-- reference is stored in Redis under mcp:confirm:{ref} with this TTL, so expiry is an
-- automatic end-of-life (no background sweep needed, R57 lifecycle bound at the
-- creation point). The value is hot-updatable through tp_sys_config and read live on
-- every issuance; illegal or non-positive values fall back to the shipped default.
-- The shipped default stays in sync with DEFAULT_TTL_SECONDS on McpConfirmGrantStore
-- (drift between them is a defect). Idempotent replay.
INSERT INTO tp_sys_config (config_key, config_value, group_name, value_type, encrypt_flag, description) VALUES
('mcp.confirm.ttl-seconds', '1800', '系统', 'int', 0, '站外智能体写操作确认码的有效期秒数（默认 1800，即 30 分钟；过期后确认码自动作废，重新发起写操作即可拿到新的确认码）')
ON CONFLICT (config_key) DO NOTHING;

-- ################ V554__exec_step_heal_evidence.sql ################
-- V554__exec_step_heal_evidence.sql — direct-heal evidence rows relayed by
-- the executor (03 protocol 2.4 trailing key stepHealEvidence, Page Element
-- Library self-heal ledger). One row per healed step: which element healed,
-- which anchor failed, which anchor won, at what visual similarity and what
-- ledger revision — the audit trail behind a self-healed run (executor
-- records, core stores verbatim; no scoring happens here).
-- R57: rows are bounded by the task FK (ON DELETE CASCADE) — retention
-- cleanup of a task drops its evidence with it. element_id carries no FK on
-- purpose: a ledger element retired after the run must never destroy the
-- historical evidence (the row is the record, not a pointer).
CREATE TABLE IF NOT EXISTS tp_exec_step_heal_evidence (
    id                  BIGSERIAL PRIMARY KEY,
    task_id             BIGINT      NOT NULL REFERENCES tp_exec_task (id) ON DELETE CASCADE,
    element_id          BIGINT,
    step_no             INT,
    healed              BOOLEAN,
    first_anchor_failed BOOLEAN,
    from_anchor_type    VARCHAR(32),
    from_anchor_value   TEXT,
    used_anchor_type    VARCHAR(32),
    used_anchor_value   TEXT,
    viewport            VARCHAR(32),
    ledger_revision     INT,
    similarity_score    DOUBLE PRECISION,
    created_at          TIMESTAMP   NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_step_heal_evidence_element
    ON tp_exec_step_heal_evidence (element_id, id DESC);
CREATE INDEX IF NOT EXISTS idx_step_heal_evidence_task
    ON tp_exec_step_heal_evidence (task_id);

COMMENT ON TABLE tp_exec_step_heal_evidence IS 'Self-heal evidence rows relayed with execution results (stepHealEvidence trailing key); bounded by task cascade.';
COMMENT ON COLUMN tp_exec_step_heal_evidence.task_id IS 'Owning execution task; ON DELETE CASCADE keeps the table bounded with task retention.';
COMMENT ON COLUMN tp_exec_step_heal_evidence.element_id IS 'Ledger element that was healed; FK-free by design so a retired element never destroys historical evidence.';
COMMENT ON COLUMN tp_exec_step_heal_evidence.step_no IS 'Action step index in the script where the first anchor failed and a later anchor healed.';
COMMENT ON COLUMN tp_exec_step_heal_evidence.from_anchor_type IS 'Anchor class that failed first (css|xpath|text|placeholder|alt|testid|rel).';
COMMENT ON COLUMN tp_exec_step_heal_evidence.from_anchor_value IS 'Failed locator expression itself.';
COMMENT ON COLUMN tp_exec_step_heal_evidence.used_anchor_type IS 'Anchor class that finally resolved the element.';
COMMENT ON COLUMN tp_exec_step_heal_evidence.used_anchor_value IS 'Healing locator expression itself.';
COMMENT ON COLUMN tp_exec_step_heal_evidence.viewport IS 'Execution bucket label (e.g. 1440x900) the heal happened under.';
COMMENT ON COLUMN tp_exec_step_heal_evidence.ledger_revision IS 'Page Element Library revision the element ledger was at when the heal was reported.';
COMMENT ON COLUMN tp_exec_step_heal_evidence.similarity_score IS 'Visual similarity against the baseline screenshot at heal time; NULL = no baseline to compare against (unproven).';

-- ################ V555__script_writeback_reproof_ttl_seconds.sql ################
-- V555__script_writeback_reproof_ttl_seconds.sql — ledger window key for the
-- platform re-validation of landed off-site script write-backs.
-- Seeds script.writeback.reproof.ttl-seconds (factory default 86400 = 24 hours):
-- the lifetime of the one-shot Redis ledger entry script:reproof:{taskId} that
-- links a write-back landing to its platform trial-run task. When the trial
-- settles (pass or fail) the entry is consumed immediately; when the task never
-- settles the entry lapses with this TTL, so no stale ledger accumulates
-- (automatic end-of-life, R57 lifecycle bound at the creation point). The value
-- is hot-updatable through tp_sys_config and read live on every scheduling;
-- illegal or non-positive values fall back to the shipped default.
-- The shipped default stays in sync with DEFAULT_TTL_SECONDS on
-- ScriptWritebackPlatformReproof (drift between them is a defect).
-- Idempotent replay.
INSERT INTO tp_sys_config (config_key, config_value, group_name, value_type, encrypt_flag, description) VALUES
('script.writeback.reproof.ttl-seconds', '86400', '系统', 'int', 0, '脚本写回后平台试运行复证台账的有效期秒数（默认 86400，即 24 小时；试运行出结果即销账，任务长时间未出结果时台账到期自动失效，重新发起写回即可触发新的复证）')
ON CONFLICT (config_key) DO NOTHING;

-- ################ V556__web_element_variants_column.sql ################
-- V556__web_element_variants_column.sql — cross-viewport variants column (WE batch S4 prep, design 8.2).
-- A ledger row's top-level anchors stay the any/default viewport set; this
-- column carries per-viewport-class anchor sets so a responsive page keeps
-- one asset per element instead of one row per breakpoint class.
--   variants: [{ "viewport": "mobile|tablet|desktop", "anchors": [ ... ] }]
--   Empty array = single-viewport asset: every existing read/write path and
--   the dispatch snapshot behave exactly as before (zero behaviour drift for
--   stored rows).
ALTER TABLE tp_web_element
    ADD COLUMN IF NOT EXISTS variants JSONB NOT NULL DEFAULT '[]'::jsonb;
ALTER TABLE tp_web_element
    DROP CONSTRAINT IF EXISTS ck_web_element_variants_array;
ALTER TABLE tp_web_element
    ADD CONSTRAINT ck_web_element_variants_array
    CHECK (jsonb_typeof(variants) = 'array');

COMMENT ON COLUMN tp_web_element.variants IS 'Per-viewport-class anchor sets: [{viewport: mobile|tablet|desktop, anchors: ordered anchor array}]; empty array means the element is a single-viewport asset and the top-level anchors apply to every viewport.';

-- Hot-updatable key for the survey collection classes (design 8.2 collection
-- rule). The survey step re-collects the candidate pool once per declared
-- class; an environment profile that declares no viewport class keeps the
-- default tier only and stores an empty variants array.
INSERT INTO tp_sys_config (config_key, config_value, group_name, value_type, encrypt_flag, description) VALUES
('element.viewport-classes', 'mobile,tablet,desktop', '系统', 'string', 0, '整页测绘时逐档重采并装配变体锚集的视口档清单（逗号分隔，可填 mobile、tablet、desktop 的组合；被测环境档案未声明视口档时只采当前默认档，变体清单保持为空；改档后下一次测绘即生效）')
ON CONFLICT (config_key) DO NOTHING;

-- ################ V557__ai_review_auto_approve_keys.sql ################
-- V557__ai_review_auto_approve_keys.sql — factory seeds for the optional quick-review
-- auto-approve channel . Two keys:
--   * ai.review.auto-approve.enabled — ships OFF on purpose. Relaxing the human
--     review quality gate is a red-line exception surface: silence is not consent,
--     any flip must be an explicit user order. While off, every pending-review case
--     keeps waiting for a human reviewer exactly as before.
--   * ai.review.auto-approve.min-grade — the evidence-grade floor a case must reach
--     before the channel may consider it (3 = platform re-proof passed, the grade
--     ScriptWritebackPlatformReproof raises the case to when a trial run succeeds).
-- High AI self-assessed confidence (1) and the security-tag exemption are enforced
-- in code (AiReviewAutoApprovePolicy), never through these keys, and the exemption
-- cannot be lifted by the switch. Idempotent replay.
--
-- Flyway is not wired in this project: apply manually to the target database (DBA
-- path in production), then regenerate db/schema-init.sql with tools/ops/gen_schema_init.sh.

INSERT INTO tp_sys_config (config_key, config_value, group_name, value_type, encrypt_flag, description) VALUES
    ('ai.review.auto-approve.enabled', '0', '系统', 'string', 0,
     '快速评审自动通过开关（默认关闭：待评审用例照常等待人工评审。打开后：平台复证已通过、AI 自评为高置信的用例自动记为已通过并留评审记录；打了「安全」类标签的用例不受本开关影响，始终人工评审。在本页修改即时生效）'),
    ('ai.review.auto-approve.min-grade', '3', '系统', 'int', 0,
     '快速评审自动通过要求的最低证据分级（默认 3；1=站外自报无实证，2=站外实证在案，3=平台复证通过。证据分级达到该值且 AI 自评为高置信的用例才会被自动通过）')
ON CONFLICT (config_key) DO NOTHING;

-- ################ V558__web_element_survey_naming_keys.sql ################
-- V558: WE batch segment P3 — AI semantic naming for page-survey candidates.
-- * governance key ai.element.naming.enabled: factory default on (AI features
--   ship enabled; only an explicit 0/false closes the naming round, which then
--   burns zero model calls and writes zero ledger rows; a missing row keeps
--   naming on).
-- * seed row: the naming instruction head, carried verbatim from the built-in
--   conservative fallback so the key-echo and JSON output requirements stay
--   coupled to the parser; status=2 (full release). Missing row or a failed
--   read falls back to the built-in head — the prompt is never empty.
-- All inserts are replay-safe (ON CONFLICT DO NOTHING).
INSERT INTO tp_sys_config (config_key, config_value, group_name, value_type, encrypt_flag, description) VALUES
    ('ai.element.naming.enabled', 'true', '系统', 'bool', 0,
     '页面元素测绘命名开关（默认开启；开启时测绘候选的业务语义名由大模型按「提示词模板」页面 web-element-survey-naming 的已发布内容生成，模板没有已发布内容时按内置命名指令执行；关闭或模型不可用时保留规则采集的名称，候选入账不受影响。修改即时生效，无需重启）')
ON CONFLICT (config_key) DO NOTHING;

INSERT INTO tp_prompt_template (name, domain, version, content, status, created_by) VALUES
('web-element-survey-naming', 'web-element', 1,
$$你是页面元素命名员。给定同一页面内的交互元素候选清单（key=定位锚身份，text=可见文本，role/nearby=可选补充），为每个你能确定业务含义的候选起一个 12 字内的中文业务语义名。
只输出一个 JSON 对象，不要输出其他文字，格式：{"names":[{"key":"原样回传的key","name":"业务语义名"}]}
判断不了的候选直接省略；禁止编造名称；key 必须逐字原样回传。$$,
 2, 0)
ON CONFLICT (name, domain, version) DO NOTHING;

-- ################ V559__help_web_element_survey_amend.sql ################
-- Migration V559: R61 help-chapter amendment for the manual page survey and
-- the whole-page candidate approval on the Page Element Library page
-- Idempotent: the append is guarded by IS DISTINCT FROM on the marker text,
-- replay after the amendment writes zero rows.

UPDATE tp_help_doc
   SET body_md = body_md || E'\n\n## 整页测绘与批量批准（新增能力）\n'
       || E'不想逐个登记元素时，点筛选带右侧的「测绘此页」：填写页面完整 URL 并点「开始测绘」，系统打开该页面一次采齐可见控件，自动生成业务化名称（如「登录按钮」）与候选定位锚。测绘在后台分批进行，弹窗提示「测绘任务已发起（会话 N）」，点「刷新」即可看到候选条目陆续进入列表。\n'
       || E'- 候选锚攒多了逐条点太慢：展开页面行，头部显示「本页还有 N 条候选等待批准」，点「全部批准入库」一键把这一页的候选升为已确认；每一条仍逐条走确认版本校验并留一笔审计事件，任何一条失败会点名成功与失败数量，不会假装全部成功。\n'
       || E'- 视口档：环境档案声明了 mobile/tablet/desktop 档位时，测绘按档逐档重采并合并成跨视口变体锚；未声明档位只采默认视口，不猜测。\n'
       || E'- 未选项目时按钮不可用；页面地址留空会被拒绝并说明需要先填写完整 URL。\n'
       || E'- 成本透明：每次测绘的命名请求都会记入 AI 调用日志（独立功能标签），在用量页可查，不存在看不见的外呼。\n'
  WHERE domain_code = 'F'
    AND title = '页面元素库：Web 定位锚集中建档'
    AND body_md NOT LIKE '%整页测绘与批量批准（新增能力）%';

