-- ################ V609__web_element_health_daily.sql ################
-- Migration: WE-S7 8.3 step-health account (package 1 of the observation
-- close-out). tp_web_element_anchor_stat (V550) is a cumulative account, so
-- a rolling time window needs its own daily rollup: the result-relay hook
-- UPSERTs today's (element, viewport) deltas here and prunes rows past the
-- account horizon in the same step (R57 — creation point paired with a
-- bounded lifetime: horizon = window-days * 4, covering the three windows
-- the drift ladder reads plus one day of slack). Health badges and the
-- "about to break" warning are pure SQL reads over this table, zero model
-- calls. The thresholds and the window size are hot keys in tp_sys_config
-- (live source; read with clamp + fallback, never hardcoded elsewhere).
CREATE TABLE IF NOT EXISTS tp_web_element_health_daily (
    bucket_date DATE        NOT NULL,
    element_id  BIGINT      NOT NULL REFERENCES tp_web_element (id) ON DELETE CASCADE,
    viewport    VARCHAR(32) NOT NULL,
    hits        BIGINT      NOT NULL DEFAULT 0,
    misses      BIGINT      NOT NULL DEFAULT 0,
    updated_at  TIMESTAMP   NOT NULL DEFAULT now(),
    CONSTRAINT pk_web_element_health_daily PRIMARY KEY (bucket_date, element_id, viewport),
    CONSTRAINT ck_health_daily_hits CHECK (hits >= 0),
    CONSTRAINT ck_health_daily_misses CHECK (misses >= 0)
);

CREATE INDEX IF NOT EXISTS idx_web_element_health_daily_element
    ON tp_web_element_health_daily (element_id, bucket_date DESC);

COMMENT ON TABLE tp_web_element_health_daily IS 'Daily anchor hit/miss rollup per (element, viewport bucket), written by the executor result relay; rows older than the health horizon are pruned by the same hook (WE S7 8.3).';
COMMENT ON COLUMN tp_web_element_health_daily.bucket_date IS 'UTC-free server date bucket (CURRENT_DATE at relay time); the health service reads rolling windows from this column only.';
COMMENT ON COLUMN tp_web_element_health_daily.viewport IS 'Execution bucket label, same vocabulary as tp_web_element_anchor_stat (columnar rule: buckets never merge on write; the health read merges per element by design §8.3).';

-- Hot-updatable health knobs (idempotent replay; tp_sys_config is the live source).
INSERT INTO tp_sys_config (config_key, config_value, group_name, value_type, encrypt_flag, description) VALUES
('element.health.miss-warn', '20', '系统', 'int', 0, '健康列黄色档位起点：最近统计窗口内未命中比例达到该百分比时该行标黄（可设 0~100，保存即生效；低于该值标绿）'),
('element.health.miss-bad', '50', '系统', 'int', 0, '健康列红色档位起点：最近统计窗口内未命中比例达到该百分比时该行标红（可设 0~100，保存即生效；设置低于黄色起点时按黄色起点处理）'),
('element.health.window-days', '7', '系统', 'int', 0, '健康度统计的天数窗口（可设 1~30，保存即生效；未命中比例与连续上升预警都按该窗口分段计算）')
ON CONFLICT (config_key) DO NOTHING;

-- ################ V610__web_element_storm_events.sql ################
-- Migration: WE-S7 A7 revision-storm ledger (package 2 of the observation
-- close-out). An element entering STALE from the single write choke point
-- (WebElementServiceImpl.changeState) drops one row here. tp_web_element
-- .updated_at cannot carry the "went stale at" fact (any unrelated edit
-- re-stamps it), so the storm window is computed over this table only.
-- R57 bounded lifetime at the creation point: every insert prunes rows
-- older than window-hours * 4 in the same call (no scheduler, no growth).
-- The window size and the entry count are hot keys in tp_sys_config
-- (live source; read with clamp + fallback, never hardcoded elsewhere).
CREATE TABLE IF NOT EXISTS tp_web_element_stale_event (
    id           BIGSERIAL PRIMARY KEY,
    element_id   BIGINT      NOT NULL REFERENCES tp_web_element (id) ON DELETE CASCADE,
    project_id   BIGINT      NOT NULL REFERENCES tp_project (id),
    page_key     VARCHAR(200) NOT NULL,
    occurred_at  TIMESTAMP   NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_web_element_stale_event_page
    ON tp_web_element_stale_event (project_id, page_key, occurred_at DESC);

COMMENT ON TABLE tp_web_element_stale_event IS 'One row per element entering the stale state, written by the state-change choke point; rows past the storm horizon are pruned by the same insert (revision-storm aggregation, WE S7 A7).';
COMMENT ON COLUMN tp_web_element_stale_event.occurred_at IS 'Server timestamp of the stale transition; the rolling storm window filters on this column only.';

-- Hot-updatable storm knobs (idempotent replay; tp_sys_config is the live source).
INSERT INTO tp_sys_config (config_key, config_value, group_name, value_type, encrypt_flag, description) VALUES
('element.storm.window-hours', '24', '系统', 'int', 0, '改版事件聚合的时间窗口（小时，可设 1~168，保存即生效）：窗口内同一页面进入陈旧的条目达到门槛数量时视为一次改版事件，并在页面元素库看板给出批量试运行建议'),
('element.storm.entry-min', '3', '系统', 'int', 0, '改版事件判定门槛（可设 2~50，保存即生效）：同一统计窗口或同一统计周期内，同页进入陈旧（或标记将坏）的条目数达到该值才聚合为改版事件，低于该值不预警')
ON CONFLICT (config_key) DO NOTHING;

-- ################ V611__fidelity_reused_source_scope.sql ################
-- Reuse-scoped fidelity (ticket 1 follow-up of the D1 triage): a generation
-- that answers buckets from the proven cross-run bucket-result cache, or a
-- whole group from the per-generation item cache, covers that source scope
-- WITHOUT a fresh provider call. The new column books the covered scope so
-- the ledger can answer retention = (injected + reused) / source instead of
-- scoring a zero-call reuse leg against the whole document (the live false
-- red: generation 710db3de booked injected 6714 / source 13481 = 49.80 for
-- a document whose unchanged buckets were fully reused). Rows written
-- before this column keep the legacy face (0 = nothing reused = the old
-- arithmetic byte-identical); the whole-document floor semantics of fresh
-- full-document rounds never change.
ALTER TABLE tp_doc_extract_fidelity
    ADD COLUMN IF NOT EXISTS reused_source_tokens INT NOT NULL DEFAULT 0;

COMMENT ON COLUMN tp_doc_extract_fidelity.reused_source_tokens IS
    'Source tokens this generation covered by cache reuse instead of a fresh provider call (read-by-reuse face of the reuse-scoped retention).';

